const HFB_GROUPS = [
  { id: "hfb_living", label: "Living room", hfbLabel: "HFB 1–2", spotIds: ["sr_lrstorage", "sr_lr1", "sr_lr2"] },
  { id: "hfb_dining_kitchen", label: "Dining & Kitchen", hfbLabel: "HFB 7–8", spotIds: ["sr_dining", "sr_kitchen"] },
  { id: "hfb_bedroom", label: "Bedroom", hfbLabel: "HFB 4–5", spotIds: ["sr_bedstorage", "sr_bedroom1", "sr_bedroom2"] },
  { id: "hfb_workspace_children", label: "Workspace & Children", hfbLabel: "HFB 3, 9", spotIds: ["sr_workspace", "sr_children"] },
  { id: "hfb_cookshop", label: "Cookshop", hfbLabel: "HFB 14–15", spotIds: ["mh_cooking"] },
  { id: "hfb_textile_bath", label: "Textile & Bathshop", hfbLabel: "HFB 6, 11–13", spotIds: ["mh_hometextiles1", "mh_hometextiles2", "mh_bedtextiles", "mh_bathshop"] },
  { id: "hfb_homeorg_lighting", label: "Home Organization & Lighting", hfbLabel: "HFB 10, 18", spotIds: ["mh_skadis", "mh_lighting"] },
  { id: "hfb_homedeco", label: "Home Decoration", hfbLabel: "HFB 16", spotIds: ["mh_walldeco", "mh_liveplant"] },
  { id: "hfb_selfserve", label: "Self Serve", hfbLabel: "Self Serve", spotIds: ["ss1", "ss2"] },
];

// With the layout set from bangna-fixed-v11 the same commercial area exists as several
// spots (one per round layout), so an area is now recognised by its label rather than by a
// fixed list of ids. Custom spots added on the map fall through and stay ungrouped.
function getHfbGroupIdForLabel(label) {
  const l = (label || "").toLowerCase();
  if (l.includes("livingroom") || l.includes("living room")) return "hfb_living";
  if (l.includes("workspace") || l.includes("children")) return "hfb_workspace_children";
  if (l.includes("bedroom")) return "hfb_bedroom";
  if (l.includes("dining") || l.includes("kitchen")) return "hfb_dining_kitchen";
  if (l.includes("cookshop") || l.includes("cooking")) return "hfb_cookshop";
  if (l.includes("textile") || l.includes("bath shop") || l.includes("bathshop")) return "hfb_textile_bath";
  if (l.includes("home organi") || l.includes("skadis") || l.includes("lighting")) return "hfb_homeorg_lighting";
  if (l.includes("home decoration") || l.includes("wall decoration") || l.includes("live plant")) return "hfb_homedeco";
  if (l.includes("self serve") || l.includes("checkout")) return "hfb_selfserve";
  return null;
}

// The dashboard "scope" chips a manager can drill into: overall, or one of the 8 HFB groups.
// Zone-level views (Showroom / Market Hall / Self Serve) were dropped in favor of HFB granularity.
// The dashboard scope picker is two levels: a zone row, and — when a zone with HFB areas is
// chosen — a second row of that zone's HFB areas. Selecting anything here rescopes the whole
// page (metrics, selling donuts and the coworker ranking) so one control drives everything.
const ZONE_SCOPES = [
  { id: "overall", label: "Overall" },
  { id: "showroom", label: "Showroom" },
  { id: "markethall", label: "Market hall" },
  { id: "selfserve", label: "Self serve" },
];

const HFB_BY_ZONE = {
  showroom: ["hfb_living", "hfb_dining_kitchen", "hfb_bedroom", "hfb_workspace_children"],
  markethall: ["hfb_cookshop", "hfb_textile_bath", "hfb_homeorg_lighting", "hfb_homedeco"],
  selfserve: ["hfb_selfserve"],
};

// Which zone row should stay highlighted for a given scope id
function zoneOfScope(scopeId) {
  if (scopeId === "overall") return "overall";
  if (HFB_BY_ZONE[scopeId]) return scopeId;
  const zone = Object.keys(HFB_BY_ZONE).find((z) => HFB_BY_ZONE[z].includes(scopeId));
  return zone || "overall";
}

const DASHBOARD_SCOPES = [
  { id: "overall", label: "Overall", kind: "zone" },
  ...ZONE_SCOPES.filter((z) => z.id !== "overall").map((z) => ({ id: z.id, label: z.label, kind: "zone" })),
  ...HFB_GROUPS.map((g) => ({ id: g.id, label: g.hfbLabel, sub: g.label, kind: "hfb" })),
];

// Which HFB group a given spot naturally belongs to (used to default the HFB picker in the coworker modal)
function findHfbGroupForSpot(spot) {
  const label = typeof spot === "string" ? spot : spot && spot.label;
  const gid = getHfbGroupIdForLabel(label);
  return HFB_GROUPS.find((g) => g.id === gid) || null;
}

