// The duty-name dropdown list for a function.
function dutyNamesFor(fnId) {
  return fnId === "cr" ? CR_DUTY_NAMES : SK_NAMES;
}

// Which duty person was responsible for evaluating staff during a given round, based on
// whether that round falls before or after the 14:00 morning/afternoon handover. Used only
// in raw data exports, where each row is a specific round and needs its own evaluator.
function evaluatorForRound(dayDuty, roundTime) {
  if (!dayDuty) return "";
  const isMorningRound = typeof roundTime === "string" && /^\d{2}:\d{2}$/.test(roundTime) && roundTime < "14:00";
  return ((isMorningRound ? dayDuty.morning : dayDuty.afternoon) || "").trim();
}

// Which checklist sections belong to the morning duty vs the afternoon duty. Per-person
// checklist completion credits the morning duty only for the morning sections and the
// afternoon duty only for the afternoon sections, so each is measured on the work that was
// actually theirs.
//
// Sales splits its routine by time of day. CR splits differently: the morning duty owns the
// role call plus the whole checklist report, while the afternoon duty owns just the report
// (no role call). Any section not listed for a function is treated as afternoon.
const MORNING_CHECKLIST_SECTIONS = {
  sales: ["morning_before10", "morning_media", "showroom", "markethall", "morning_after10"],
  cr: ["cr_rolecall", "cr_grooming", "cr_operation", "cr_collaborate", "cr_safety"],
};
const AFTERNOON_CHECKLIST_SECTIONS = {
  sales: ["pm_after10", "afternoon", "after2130"],
  cr: ["cr_grooming", "cr_operation", "cr_collaborate", "cr_safety"],
};
// A section can belong to both shifts (e.g. CR's report), so membership is per-shift rather
// than one-or-the-other. Returns true if the section counts toward the given shift.
function sectionInShift(fnId, key, shift) {
  const map = shift === "morning" ? MORNING_CHECKLIST_SECTIONS : AFTERNOON_CHECKLIST_SECTIONS;
  const list = map[fnId] || map.sales;
  return list.includes(key);
}
// Where the chosen function is remembered — intentionally not persisted across sessions;
// the picker is shown on every open.

// Storage keys are namespaced per function so one function's data can never touch another's.
// Sales is the exception: it was the only function before this change, so its data was saved
// under un-prefixed keys ("checklist:2026-08-21"). To avoid stranding that history, Sales
// keeps using the original keys, while every new function gets a "<fn>:" prefix.
function nsKey(fnId, base) {
  return fnId === "sales" ? base : `${fnId}:${base}`;
}

const STORAGE_KEYS = {
  duty: (fnId, date) => nsKey(fnId, `duty:${date}`),
  checks: (fnId, date) => nsKey(fnId, `checks:${date}`),
  checklist: (fnId, date) => nsKey(fnId, `checklist:${date}`),
  checklistItems: (fnId) => nsKey(fnId, `checklistItems:config-v6`), // v6: CR role-call items without prefix
  spots: (fnId) => nsKey(fnId, `spots:config-v14`),
  timeSlots: (fnId) => nsKey(fnId, `timeSlots:config-v2`),
  sellingItems: (fnId) => nsKey(fnId, `sellingItems:config`),
  teamRoster: (fnId) => nsKey(fnId, `teamRoster:config`),
  checklistSectionTitles: (fnId) => nsKey(fnId, `checklistSectionTitles:config-v5`),
  resetPin: (fnId) => nsKey(fnId, `resetPin:config`),
  dutyNames: (fnId) => nsKey(fnId, `dutyNames:config`),
};

// Sunday-start week key/label, e.g. week of Sun 13 Jul – Sat 19 Jul 2026 -> key "2026-07-13"
function sundayWeekKey(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const start = new Date(d);
  start.setDate(d.getDate() - d.getDay()); // back up to Sunday
  return `${start.getFullYear()}-${String(start.getMonth() + 1).padStart(2, "0")}-${String(start.getDate()).padStart(2, "0")}`;
}

function sundayWeekLabel(weekKey) {
  const start = new Date(weekKey + "T00:00:00");
  const end = new Date(start);
  end.setDate(start.getDate() + 6);
  const fmtStart = start.toLocaleDateString("en-US", { day: "numeric", month: "short" });
  const fmtEnd = end.toLocaleDateString("en-US", { day: "numeric", month: "short", year: "numeric" });
  return `${fmtStart} – ${fmtEnd}`;
}

function monthKey(dateStr) {
  return dateStr.slice(0, 7); // YYYY-MM
}

function monthLabel(mKey) {
  const [y, m] = mKey.split("-").map(Number);
  return new Date(y, m - 1, 1).toLocaleDateString("en-US", { month: "short", year: "numeric" });
}

function dateLabelShort(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleDateString("en-US", { weekday: "short", day: "numeric", month: "short" });
}

// IKEA physical/fiscal year: 1 September – 31 August
function getFiscalYearRange(today = new Date()) {
  const y = today.getFullYear();
  const startYear = today.getMonth() >= 8 ? y : y - 1; // Sep = month index 8
  const start = new Date(startYear, 8, 1);
  const end = new Date(startYear + 1, 7, 31);
  const toKey = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const fmt = (d) => d.toLocaleDateString("en-US", { day: "numeric", month: "short", year: "numeric" });
  return { startKey: toKey(start), endKey: toKey(end), label: `${fmt(start)} – ${fmt(end)}` };
}

// Restrict a single day's check data down to one round (time-slot index) only —
// lets the existing multi-round stat functions be reused unchanged for a single round.
function pickSlotData(dayChecks, slotIdx) {
  const out = {};
  Object.keys(dayChecks || {}).forEach((spotId) => {
    const rec = dayChecks[spotId]?.[slotIdx];
    if (rec) out[spotId] = { 0: rec };
  });
  return out;
}

/* ===================== SUPABASE STORAGE (shared team data) ===================== */
const SUPABASE_URL = "https://usukxmjavhnnwvyzusdj.supabase.co";
const SUPABASE_KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InVzdWt4bWphdmhubnd2eXp1c2RqIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIwMzY5MTQsImV4cCI6MjA5NzYxMjkxNH0.9FsD8oy4lvN_g25OvfvbKQqrXpRSJ9Gj7TRUKcVZ4FI";

const sbHeaders = {
  "apikey": SUPABASE_KEY,
  "Authorization": `Bearer ${SUPABASE_KEY}`,
  "Content-Type": "application/json",
};

// Supabase is the shared source of truth, but every write is mirrored to localStorage so an
// edit is never lost when the device is offline or the request fails. Reads prefer Supabase
// and fall back to the local mirror, so saved settings survive a reload either way.
const localKey = (key) => `bangna:${key}`;

function localGet(key, fallback) {
  try {
    const raw = window.localStorage.getItem(localKey(key));
    return raw === null ? fallback : JSON.parse(raw);
  } catch {
    return fallback;
  }
}

function localSet(key, value) {
  try {
    window.localStorage.setItem(localKey(key), JSON.stringify(value));
  } catch {
    /* quota or private mode — Supabase still has the write */
  }
}

async function storageGet(key, fallback) {
  try {
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/app_storage?key=eq.${encodeURIComponent(key)}&select=value`,
      { headers: sbHeaders }
    );
    if (!res.ok) return localGet(key, fallback);
    const rows = await res.json();
    if (rows && rows.length > 0) {
      localSet(key, rows[0].value);
      return rows[0].value;
    }
    return localGet(key, fallback);
  } catch {
    return localGet(key, fallback);
  }
}

async function storageSet(key, value) {
  localSet(key, value);
  try {
    const res = await fetch(`${SUPABASE_URL}/rest/v1/app_storage`, {
      method: "POST",
      headers: { ...sbHeaders, "Prefer": "resolution=merge-duplicates" },
      body: JSON.stringify({ key, value, updated_at: new Date().toISOString() }),
    });
    if (!res.ok) console.error("storage set failed", res.status, await res.text());
  } catch (e) {
    console.error("storage set failed", e);
  }
}
async function storageList(prefix) {
  try {
    const res = await fetch(
      `${SUPABASE_URL}/rest/v1/app_storage?key=like.${encodeURIComponent(prefix)}*&select=key`,
      { headers: sbHeaders }
    );
    if (!res.ok) return [];
    const rows = await res.json();
    return rows.map((r) => r.key);
  } catch {
    return [];
  }
}
async function storageDeleteByPrefix(prefix) {
  try {
    await fetch(`${SUPABASE_URL}/rest/v1/app_storage?key=like.${encodeURIComponent(prefix)}*`, {
      method: "DELETE",
      headers: sbHeaders,
    });
  } catch (e) {
    console.error("storage delete failed", e);
  }
}

