/* ===================== DUTY VIEW ===================== */
// Colour a person's avatar from their name so the same coworker keeps the same colour
// everywhere in the log book without needing a stored preference.
const AVATAR_COLORS = ["#378ADD", "#BA7517", "#1D9E75", "#D4537E", "#7F77DD", "#D85A30"];
function avatarColor(name) {
  let sum = 0;
  for (let i = 0; i < (name || "").length; i++) sum += name.charCodeAt(i);
  return AVATAR_COLORS[sum % AVATAR_COLORS.length];
}

function Avatar({ name, size = 26 }) {
  const initial = (name || "?").trim().charAt(0).toUpperCase() || "?";
  return (
    <span
      style={{
        width: size, height: size, borderRadius: "50%", flexShrink: 0,
        background: name ? avatarColor(name) : "#D1D5DB", color: "#fff",
        fontSize: size * 0.42, fontWeight: 700,
        display: "flex", alignItems: "center", justifyContent: "center",
      }}
    >
      {initial}
    </span>
  );
}

// Defined at module scope (not inside DutyView) so it keeps its identity across renders.
// When this lived inside DutyView it was re-created on every keystroke, which unmounted and
// remounted the <input>, stealing focus after each character — that was the "typing feels
// stuck" bug. As a top-level component the input stays mounted and typing is smooth; each
// field saves itself as you type, so there's nothing to remember to do afterwards.
function DutyShiftCard({ name, onNameChange, note, onNoteChange, label, hours, notePlaceholder, nameOptions, selectPlaceholder, onEditNames }) {
  return (
    <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 12 }}>
        <Avatar name={name} />
        <div style={{ flex: 1 }}>
          <div style={{ fontSize: 13, fontWeight: 700 }}>{label}</div>
          <div style={{ fontSize: 10.5, color: "#9CA3AF" }}>{hours}</div>
        </div>
        {onEditNames && (
          <button
            onClick={onEditNames}
            style={{
              display: "flex", alignItems: "center", gap: 4, border: "none", background: "transparent",
              color: "#0058A3", fontSize: 12, fontWeight: 700, padding: "4px 2px", flexShrink: 0,
            }}
          >
            <Icon name="edit" size={12} />
            Edit names
          </button>
        )}
      </div>
      <select
        value={name}
        onChange={(e) => onNameChange(e.target.value)}
        style={{ ...inputStyle, marginBottom: 12, color: name ? "#15181F" : "#9CA3AF", background: "#fff" }}
      >
        <option value="">{selectPlaceholder || "Select name…"}</option>
        {(nameOptions || []).map((n) => (
          <option key={n} value={n} style={{ color: "#15181F" }}>{n}</option>
        ))}
      </select>
      <FieldLabel icon="list" text="Handover note" />
      <input
        value={note}
        onChange={(e) => onNoteChange(e.target.value)}
        placeholder={notePlaceholder}
        style={{ ...inputStyle, fontWeight: 400, fontSize: 13.5 }}
      />
    </div>
  );
}

function DutyView({ fn, duty, saveDuty, checklist, checklistItems, checks, todaySlots, spotsConfig, timeSlots, dutyNames, saveDutyNames }) {
  const [view, setView] = useState("today"); // today | log
  const [showNamesModal, setShowNamesModal] = useState(false);
  const [morning, setMorning] = useState(duty.morning || "");
  const [afternoon, setAfternoon] = useState(duty.afternoon || "");
  const [morningHandover, setMorningHandover] = useState(duty.morningHandover || "");
  const [afternoonHandover, setAfternoonHandover] = useState(duty.afternoonHandover || "");

  const [history, setHistory] = useState([]);
  const [loadingHistory, setLoadingHistory] = useState(true);
  const [query, setQuery] = useState("");
  const [openDate, setOpenDate] = useState(null);

  useEffect(() => {
    setMorning(duty.morning || "");
    setAfternoon(duty.afternoon || "");
    setMorningHandover(duty.morningHandover || "");
    setAfternoonHandover(duty.afternoonHandover || "");
  }, [duty]);

  // Each log entry pulls in that day's checklist ticks and availability checks too, so a
  // handover note can be read next to how the day actually went.
  useEffect(() => {
    (async () => {
      const keys = await storageList("duty:");
      const dates = keys
        .map((k) => k.replace("duty:", ""))
        .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
        .sort()
        .reverse();

      const results = await Promise.all(
        dates.map(async (date) => {
          const [d, cl, ck] = await Promise.all([
            storageGet(`duty:${date}`, {}),
            storageGet(`checklist:${date}`, {}),
            storageGet(`checks:${date}`, {}),
          ]);

          let done = 0, total = 0;
          Object.keys(checklistItems || {}).forEach((key) => {
            const items = (checklistItems || {})[key] || [];
            total += items.length;
            done += items.filter((it) => cl[key]?.[it.id]).length;
          });

          const dayRounds = (timeSlots && timeSlots[getDayType(date)]) || [];
          const roundsDone = dayRounds.filter((_, i) =>
            spotsConfig.some((s) => ck[s.id]?.[i]?.status)
          ).length;

          const avg = computeDayAverages(ck, dayRounds, spotsConfig);

          return {
            date,
            morning: d.morning || "",
            afternoon: d.afternoon || "",
            morningHandover: d.morningHandover || "",
            afternoonHandover: d.afternoonHandover || "",
            checklistRate: total > 0 ? Math.round((done / total) * 100) : null,
            roundsDone,
            roundsTotal: dayRounds.length,
            availRate: avg.availRate,
          };
        })
      );
      setHistory(results.filter((r) => r.morning || r.afternoon || r.morningHandover || r.afternoonHandover));
      setLoadingHistory(false);
    })();
  }, [duty, checklistItems, spotsConfig, timeSlots]);

  // Persist a single field using the latest value of every field. Reading the other three
  // from state at call time (rather than from a closure captured when the card rendered)
  // avoids saving stale values, and lets each input save independently the moment it changes.
  const persistField = (field, value) => {
    const next = {
      morning, afternoon,
      morningHandover, afternoonHandover,
      [field]: value,
    };
    saveDuty(next);
  };

  // Today's headline numbers, so the duty manager sees the state of play without leaving
  // this page.
  const todayStats = useMemo(() => {
    let done = 0, total = 0;
    Object.keys(checklistItems || {}).forEach((key) => {
      const items = (checklistItems || {})[key] || [];
      total += items.length;
      done += items.filter((it) => checklist[key]?.[it.id]).length;
    });
    const rounds = (todaySlots || []).filter((_, i) => spotsConfig.some((s) => checks[s.id]?.[i]?.status)).length;
    const avg = computeDayAverages(checks, todaySlots || [], spotsConfig);
    return {
      checklistRate: total > 0 ? Math.round((done / total) * 100) : null,
      roundsDone: rounds,
      roundsTotal: (todaySlots || []).length,
      availRate: avg.availRate,
    };
  }, [checklist, checklistItems, checks, todaySlots, spotsConfig]);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return history;
    return history.filter((r) =>
      [dateLabelShort(r.date), r.morning, r.afternoon, r.morningHandover, r.afternoonHandover]
        .join(" ").toLowerCase().includes(q)
    );
  }, [history, query]);

  const rateColor = (v) => (v === null ? "#9CA3AF" : v >= 85 ? "#2E7D32" : v >= 70 ? "#B8590B" : "#D62B2B");

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {/* Today / Log book */}
      <div style={{ display: "flex", gap: 6 }}>
        {[{ id: "today", label: "Today" }, { id: "log", label: "Log book" }].map((t) => (
          <button
            key={t.id}
            onClick={() => setView(t.id)}
            style={{
              flex: 1, padding: "9px 4px", borderRadius: 9, border: "1.5px solid",
              borderColor: view === t.id ? "#0058A3" : "#E5E7EB",
              background: view === t.id ? "#EAF2FA" : "#fff",
              color: view === t.id ? "#0058A3" : "#6B7280",
              fontSize: 12.5, fontWeight: 700,
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      {view === "today" ? (
        <>
          <DutyShiftCard
            name={morning}
            onNameChange={(v) => { setMorning(v); persistField("morning", v); }}
            note={morningHandover}
            onNoteChange={(v) => { setMorningHandover(v); persistField("morningHandover", v); }}
            label="Morning duty" hours="Store open → 14:00"
            notePlaceholder="Anything the afternoon shift should know"
            nameOptions={dutyNames}
            selectPlaceholder={fn.id === "cr" ? "Select CR duty…" : "Select shopkeeper…"}
            onEditNames={() => setShowNamesModal(true)}
          />
          <DutyShiftCard
            name={afternoon}
            onNameChange={(v) => { setAfternoon(v); persistField("afternoon", v); }}
            note={afternoonHandover}
            onNoteChange={(v) => { setAfternoonHandover(v); persistField("afternoonHandover", v); }}
            label="Afternoon duty" hours="14:00 → store close"
            notePlaceholder="Anything the closing team should know"
            nameOptions={dutyNames}
            selectPlaceholder={fn.id === "cr" ? "Select CR duty…" : "Select shopkeeper…"}
          />

          <div style={{ display: "grid", gridTemplateColumns: fn.hasMap ? "repeat(3, minmax(0,1fr))" : "1fr", gap: 8 }}>
            {(fn.hasMap ? [
              { label: "Checklist", value: todayStats.checklistRate === null ? "—" : `${todayStats.checklistRate}%` },
              { label: "Rounds", value: `${todayStats.roundsDone}/${todayStats.roundsTotal}` },
              { label: "Avail", value: todayStats.availRate === null ? "—" : `${todayStats.availRate}%` },
            ] : [
              { label: "Checklist today", value: todayStats.checklistRate === null ? "—" : `${todayStats.checklistRate}%` },
            ]).map((s) => (
              <div key={s.label} style={{ background: "#F4F5F7", borderRadius: 10, padding: "10px 11px" }}>
                <div style={{ fontSize: 10.5, color: "#6B7280", fontWeight: 600 }}>{s.label}</div>
                <div style={{ fontSize: 19, fontWeight: 800, marginTop: 1 }}>{s.value}</div>
              </div>
            ))}
          </div>

          <div style={{ fontSize: 11.5, color: "#9CA3AF", textAlign: "center" }}>
            Saves automatically when you leave the field
          </div>
        </>
      ) : (
        <>
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search a name or a note"
            style={{ ...inputStyle, fontWeight: 400, fontSize: 13 }}
          />

          {loadingHistory ? (
            <div style={{ textAlign: "center", padding: "22px 0", color: "#9CA3AF", fontSize: 12.5 }}>
              Loading duty history...
            </div>
          ) : filtered.length === 0 ? (
            <div style={{ textAlign: "center", padding: "22px 0", color: "#9CA3AF", fontSize: 12.5 }}>
              {history.length === 0 ? "No duty history yet." : "Nothing matches that search."}
            </div>
          ) : (
            filtered.map((r) => {
              const open = openDate === r.date;
              return (
                <div key={r.date} style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: open ? "13px 15px" : "11px 15px" }}>
                  <button
                    onClick={() => setOpenDate(open ? null : r.date)}
                    style={{ width: "100%", display: "flex", alignItems: "center", gap: 8, border: "none", background: "transparent", padding: 0, textAlign: "left" }}
                  >
                    <div style={{ display: "flex", flexShrink: 0 }}>
                      <Avatar name={r.morning} size={24} />
                      <span style={{ marginLeft: -7 }}><Avatar name={r.afternoon} size={24} /></span>
                    </div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 12.5, fontWeight: 700 }}>{dateLabelShort(r.date)}</div>
                      <div style={{ fontSize: 9.5, color: "#9CA3AF", marginTop: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                        {(r.morning || "—")} → {(r.afternoon || "—")} · {r.roundsDone}/{r.roundsTotal} rounds
                      </div>
                    </div>
                    {r.checklistRate !== null && (
                      <span style={{ fontSize: 12.5, fontWeight: 800, color: rateColor(r.checklistRate), flexShrink: 0 }}>
                        {r.checklistRate}%
                      </span>
                    )}
                    <Icon name={open ? "chevronDown" : "chevronRight"} size={15} className="" />
                  </button>

                  {open && (
                    <>
                      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0,1fr))", gap: 7, marginTop: 12 }}>
                        {[
                          { label: "Checklist", value: r.checklistRate === null ? "—" : `${r.checklistRate}%`, color: rateColor(r.checklistRate) },
                          { label: "Rounds", value: `${r.roundsDone}/${r.roundsTotal}`, color: "#15181F" },
                          { label: "Avail", value: r.availRate === null ? "—" : `${r.availRate}%`, color: rateColor(r.availRate) },
                        ].map((s) => (
                          <div key={s.label} style={{ background: "#F4F5F7", borderRadius: 9, padding: "8px 9px" }}>
                            <div style={{ fontSize: 9.5, color: "#6B7280", fontWeight: 600 }}>{s.label}</div>
                            <div style={{ fontSize: 15, fontWeight: 800, color: s.color, marginTop: 1 }}>{s.value}</div>
                          </div>
                        ))}
                      </div>

                      <div style={{ marginTop: 11, paddingLeft: 9, borderLeft: "2px solid #B5D4F4", borderRadius: 0 }}>
                        <div style={{ fontSize: 10, fontWeight: 700, color: "#0058A3" }}>
                          Morning{r.morning ? ` · ${r.morning}` : ""}
                        </div>
                        <div style={{ fontSize: 12, color: "#6B7280", lineHeight: 1.5, marginTop: 2 }}>
                          {r.morningHandover || <span style={{ color: "#D1D5DB" }}>No note</span>}
                        </div>
                      </div>

                      <div style={{ marginTop: 9, paddingLeft: 9, borderLeft: "2px solid #FAC775", borderRadius: 0 }}>
                        <div style={{ fontSize: 10, fontWeight: 700, color: "#B8590B" }}>
                          Afternoon{r.afternoon ? ` · ${r.afternoon}` : ""}
                        </div>
                        <div style={{ fontSize: 12, color: "#6B7280", lineHeight: 1.5, marginTop: 2 }}>
                          {r.afternoonHandover || <span style={{ color: "#D1D5DB" }}>No note</span>}
                        </div>
                      </div>
                    </>
                  )}
                </div>
              );
            })
          )}
        </>
      )}

      {showNamesModal && (
        <DutyNamesModal
          names={dutyNames}
          saveNames={saveDutyNames}
          label={fn.id === "cr" ? "CR duty" : "shopkeeper"}
          onClose={() => setShowNamesModal(false)}
        />
      )}
    </div>
  );
}

// Editable pool of names offered in the morning/afternoon duty dropdowns, opened from the
// "Edit names" link on the duty card rather than a separate tab. Mirrors the "Edit spots"
// pattern from the Map tab: an Edit-mode toggle, tap a row to open a modal for renaming/
// deleting, and tap "Add name" to open the same modal to create one. Same component and
// behavior for every function that has duty (Sales, CR) — only the underlying name list
// differs, so editing works identically across functions.
function DutyNamesModal({ names, saveNames, label, onClose }) {
  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", zIndex: 40,
        display: "flex", alignItems: "flex-end", justifyContent: "center",
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#F4F5F7", borderRadius: "18px 18px 0 0", width: "100%", maxWidth: 480,
          padding: "20px 18px 26px", display: "flex", flexDirection: "column", gap: 12,
          maxHeight: "85vh", overflowY: "auto",
        }}
      >
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>Duty names</div>
          <button onClick={onClose} style={{ border: "none", background: "#E9EAEC", borderRadius: "50%", width: 28, height: 28, display: "flex", alignItems: "center", justifyContent: "center", color: "#6B7280" }}>
            <Icon name="x" size={14} />
          </button>
        </div>
        <DutyNamesManager names={names} saveNames={saveNames} label={label} />
      </div>
    </div>
  );
}

function DutyNamesManager({ names, saveNames, label }) {
  const [editMode, setEditMode] = useState(false);
  const [editingIdx, setEditingIdx] = useState(null); // index of name being edited, or "new"
  const [confirmDeleteIdx, setConfirmDeleteIdx] = useState(null);

  const saveName = (text) => {
    const trimmed = text.trim();
    if (!trimmed) return;
    if (editingIdx === "new") {
      if ((names || []).includes(trimmed)) { setEditingIdx(null); return; }
      saveNames([...(names || []), trimmed]);
    } else {
      saveNames((names || []).map((n, i) => (i === editingIdx ? trimmed : n)));
    }
    setEditingIdx(null);
  };

  const deleteName = (idx) => {
    saveNames((names || []).filter((_, i) => i !== idx));
    setConfirmDeleteIdx(null);
    setEditingIdx(null);
  };

  return (
    <>
      <div style={{ fontSize: 12, color: "#6B7280", lineHeight: 1.5 }}>
        Add, rename, or remove {label} names. These show up in the morning/afternoon duty
        dropdowns — {(names || []).length} {(names || []).length === 1 ? "name" : "names"} total.
      </div>

      <button
        onClick={() => setEditMode((v) => !v)}
        style={{
          display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
          border: "1.5px solid", borderColor: editMode ? "#0058A3" : "#E5E7EB",
          background: editMode ? "#0058A3" : "#fff", color: editMode ? "#fff" : "#374151",
          borderRadius: 10, padding: "10px", fontSize: 13, fontWeight: 700,
        }}
      >
        <Icon name={editMode ? "check" : "edit"} size={14} />
        {editMode ? "Done editing" : "Edit names"}
      </button>

      <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: 16 }}>
        <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: (names || []).length ? 10 : 0 }}>
          {(names || []).map((n, idx) => (
            <button
              key={`${n}-${idx}`}
              onClick={() => editMode && setEditingIdx(idx)}
              style={{
                display: "flex", alignItems: "center", gap: 8, background: "#F7F8FA", borderRadius: 9,
                padding: "10px 12px", border: "none", textAlign: "left", cursor: editMode ? "pointer" : "default",
              }}
            >
              <span style={{ flex: 1, fontSize: 13.5, fontWeight: 600, color: "#15181F" }}>{n}</span>
              {editMode && <Icon name="edit" size={14} />}
            </button>
          ))}
          {(!names || names.length === 0) && (
            <div style={{ fontSize: 12, color: "#C2C5CB", padding: "4px 2px" }}>No names added yet.</div>
          )}
        </div>

        {editMode && (
          <button
            onClick={() => setEditingIdx("new")}
            style={{
              width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
              padding: "10px", borderRadius: 10, border: "1.5px dashed #9CA3AF",
              background: "transparent", color: "#0058A3", fontSize: 13, fontWeight: 700,
            }}
          >
            <Icon name="plus" size={14} />
            Add name
          </button>
        )}
      </div>

      {editingIdx !== null && (
        <DutyNameEditModal
          initialName={editingIdx === "new" ? "" : names[editingIdx]}
          isNew={editingIdx === "new"}
          onClose={() => setEditingIdx(null)}
          onSave={saveName}
          onDeleteRequest={() => setConfirmDeleteIdx(editingIdx)}
        />
      )}

      {confirmDeleteIdx !== null && (
        <ConfirmDeleteNameModal
          label={names[confirmDeleteIdx]}
          onCancel={() => setConfirmDeleteIdx(null)}
          onConfirm={() => deleteName(confirmDeleteIdx)}
        />
      )}
    </>
  );
}

function DutyNameEditModal({ initialName, isNew, onClose, onSave, onDeleteRequest, placeholderExample }) {
  const [name, setName] = useState(initialName);

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", zIndex: 50,
        display: "flex", alignItems: "flex-end", justifyContent: "center",
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#fff", borderRadius: "18px 18px 0 0", width: "100%", maxWidth: 480,
          padding: "20px 18px 26px", display: "flex", flexDirection: "column", gap: 14,
        }}
      >
        <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>{isNew ? "Add name" : "Edit name"}</div>

        <div>
          <label style={{ fontSize: 12, fontWeight: 700, color: "#6B7280", display: "block", marginBottom: 6 }}>
            Name
          </label>
          <input
            autoFocus
            value={name}
            onChange={(e) => setName(e.target.value)}
            onKeyDown={(e) => { if (e.key === "Enter" && name.trim()) onSave(name); }}
            style={inputStyle}
            placeholder={placeholderExample || "e.g. Nam Chalakod"}
          />
        </div>

        <button
          onClick={() => name.trim() && onSave(name)}
          disabled={!name.trim()}
          style={{
            padding: "12px", borderRadius: 10, border: "none",
            background: name.trim() ? "#0058A3" : "#C2C5CB", color: "#fff",
            fontSize: 14.5, fontWeight: 700,
          }}
        >
          Save
        </button>

        {!isNew && (
          <button
            onClick={onDeleteRequest}
            style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
              padding: "11px", borderRadius: 10, border: "1.5px solid #FBD5D5",
              background: "#FDECEC", color: "#D62B2B", fontSize: 13.5, fontWeight: 700,
            }}
          >
            <Icon name="trash" size={14} />
            Delete name
          </button>
        )}

        <button
          onClick={onClose}
          style={{ padding: "10px", borderRadius: 10, border: "none", background: "transparent", color: "#6B7280", fontSize: 13.5, fontWeight: 600 }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

function ConfirmDeleteNameModal({ label, onCancel, onConfirm }) {
  return (
    <div
      onClick={onCancel}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 60,
        display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#fff", borderRadius: 16, width: "100%", maxWidth: 360,
          padding: "20px 18px", display: "flex", flexDirection: "column", gap: 12,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ color: "#D62B2B", display: "flex" }}><Icon name="alert" size={18} /></span>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>Delete this name?</div>
        </div>
        <div style={{ fontSize: 13, color: "#6B7280", lineHeight: 1.5 }}>
          "{label}" will no longer appear as an option for duty. Past records that already used
          this name are not affected.
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button
            onClick={onCancel}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#374151", fontSize: 13.5, fontWeight: 700 }}
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "none", background: "#D62B2B", color: "#fff", fontSize: 13.5, fontWeight: 700 }}
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}

function FieldLabel({ icon, text }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 9, color: "#6B7280" }}>
      <Icon name={icon} size={15} />
      <span style={{ fontSize: 12.5, fontWeight: 600 }}>{text}</span>
    </div>
  );
}

const inputStyle = {
  width: "100%", border: "1.5px solid #E5E7EB", borderRadius: 10, padding: "11px 13px",
  fontSize: 15, fontWeight: 600, outline: "none", color: "#15181F",
};

/* ===================== TEAM VIEW (HFB -> co-worker roster) ===================== */
function TeamView({ roster, saveRoster }) {
  const [addingFor, setAddingFor] = useState(null); // hfb group id currently adding a name for
  const [newName, setNewName] = useState("");
  const [editingId, setEditingId] = useState(null); // coworker id currently being renamed
  const [editText, setEditText] = useState("");
  const [search, setSearch] = useState("");

  const filteredGroups = HFB_GROUPS.filter((g) => {
    const q = search.trim().toLowerCase();
    if (!q) return true;
    return g.label.toLowerCase().includes(q) || g.hfbLabel.toLowerCase().includes(q);
  });

  const addName = (hfbId) => {
    const name = newName.trim();
    if (!name) return;
    const id = `cw_${Date.now()}`;
    const next = { ...roster, [hfbId]: [...(roster[hfbId] || []), { id, name }] };
    saveRoster(next);
    setNewName("");
    setAddingFor(null);
  };

  const removeName = (hfbId, id) => {
    const next = { ...roster, [hfbId]: (roster[hfbId] || []).filter((c) => c.id !== id) };
    saveRoster(next);
  };

  const startEdit = (c) => {
    setEditingId(c.id);
    setEditText(c.name);
  };

  const commitEdit = (hfbId) => {
    const name = editText.trim();
    if (!name) {
      setEditingId(null);
      return;
    }
    const next = {
      ...roster,
      [hfbId]: (roster[hfbId] || []).map((c) => (c.id === editingId ? { ...c, name } : c)),
    };
    saveRoster(next);
    setEditingId(null);
    setEditText("");
  };

  const totalPeople = HFB_GROUPS.reduce((sum, g) => sum + (roster[g.id] || []).length, 0);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: "13px 16px" }}>
        <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 4 }}>HFB team roster</div>
        <div style={{ fontSize: 12, color: "#6B7280", lineHeight: 1.5 }}>
          Add, rename, or remove coworkers under each HFB area. These names show up as quick-pick options
          when logging Coworker Availability on the Map tab — {totalPeople} {totalPeople === 1 ? "person" : "people"} total.
        </div>
      </div>

      <div style={{ position: "relative" }}>
        <span style={{ position: "absolute", left: 12, top: "50%", transform: "translateY(-50%)", color: "#9CA3AF", display: "flex" }}>
          <Icon name="search" size={15} />
        </span>
        <input
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder="Search by HFB (e.g. HFB1, Kitchen, Bedroom)..."
          style={{ ...inputStyle, fontWeight: 500, fontSize: 13.5, padding: "10px 12px 10px 34px" }}
        />
      </div>

      {filteredGroups.length === 0 && (
        <div style={{ textAlign: "center", padding: "24px 0", color: "#9CA3AF", fontSize: 13 }}>
          No HFB matches "{search}"
        </div>
      )}

      {filteredGroups.map((g) => {
        const list = roster[g.id] || [];
        return (
          <div key={g.id} style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: 16 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
              <div>
                <div style={{ fontSize: 14, fontWeight: 800, color: "#15181F" }}>{g.label}</div>
                <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 1 }}>{g.hfbLabel}</div>
              </div>
              <div style={{ fontSize: 11, fontWeight: 700, color: "#0058A3", background: "#EAF2FA", borderRadius: 6, padding: "3px 8px", whiteSpace: "nowrap" }}>
                {list.length} {list.length === 1 ? "person" : "people"}
              </div>
            </div>

            <div style={{ display: "flex", flexDirection: "column", gap: 6, marginBottom: 10 }}>
              {list.map((c) => (
                <div key={c.id} style={{ display: "flex", alignItems: "center", gap: 8, background: "#F7F8FA", borderRadius: 9, padding: "8px 10px" }}>
                  {editingId === c.id ? (
                    <>
                      <input
                        autoFocus
                        value={editText}
                        onChange={(e) => setEditText(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") commitEdit(g.id);
                          if (e.key === "Escape") setEditingId(null);
                        }}
                        style={{ ...inputStyle, padding: "6px 9px", fontSize: 13, flex: 1 }}
                      />
                      <button
                        onClick={() => commitEdit(g.id)}
                        style={{ border: "none", background: "#0058A3", color: "#fff", borderRadius: 7, padding: "6px 10px", fontSize: 12, fontWeight: 700, flexShrink: 0 }}
                      >
                        Save
                      </button>
                    </>
                  ) : (
                    <>
                      <span style={{ flex: 1, fontSize: 13.5, fontWeight: 600, color: "#15181F" }}>{c.name}</span>
                      <button onClick={() => startEdit(c)} style={{ border: "none", background: "transparent", color: "#6B7280", padding: 3, display: "flex", flexShrink: 0 }}>
                        <Icon name="edit" size={13} />
                      </button>
                      <button onClick={() => removeName(g.id, c.id)} style={{ border: "none", background: "transparent", color: "#D62B2B", padding: 3, display: "flex", flexShrink: 0 }}>
                        <Icon name="trash" size={13} />
                      </button>
                    </>
                  )}
                </div>
              ))}
              {list.length === 0 && (
                <div style={{ fontSize: 12, color: "#C2C5CB", padding: "4px 2px" }}>No coworkers added yet.</div>
              )}
            </div>

            {addingFor === g.id ? (
              <div style={{ display: "flex", gap: 6 }}>
                <input
                  autoFocus
                  value={newName}
                  onChange={(e) => setNewName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") addName(g.id);
                    if (e.key === "Escape") {
                      setAddingFor(null);
                      setNewName("");
                    }
                  }}
                  placeholder="Coworker name"
                  style={{ ...inputStyle, padding: "8px 10px", fontSize: 13, flex: 1 }}
                />
                <button onClick={() => addName(g.id)} style={{ padding: "8px 12px", borderRadius: 8, border: "none", background: "#0058A3", color: "#fff", fontWeight: 700, fontSize: 13, flexShrink: 0 }}>
                  Add
                </button>
                <button
                  onClick={() => {
                    setAddingFor(null);
                    setNewName("");
                  }}
                  style={{ padding: "8px 10px", borderRadius: 8, border: "none", background: "#E5E7EB", color: "#6B7280", fontSize: 13, flexShrink: 0 }}
                >
                  ✕
                </button>
              </div>
            ) : (
              <button
                onClick={() => {
                  setAddingFor(g.id);
                  setNewName("");
                }}
                style={{ display: "flex", alignItems: "center", gap: 5, background: "transparent", border: "none", color: "#0058A3", fontSize: 12.5, fontWeight: 700, padding: 0 }}
              >
                <Icon name="plus" size={12} /> Add coworker
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
}

/* ===================== MAP VIEW ===================== */
function MapView({ checks, saveChecks, latestSlotIdx, spotsConfig, saveSpotsConfig, timeSlots, saveTimeSlots, sellingItems, saveSellingItems, todayDayType, roster }) {
  const [viewDayType, setViewDayType] = useState(todayDayType || "weekday");
  const [zoneId, setZoneId] = useState(ZONES[0].id);
  const isLive = viewDayType === todayDayType;
  const [slotIdx, setSlotIdx] = useState(isLive && latestSlotIdx >= 0 ? latestSlotIdx : 0);
  const [activeSpot, setActiveSpot] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [placingNew, setPlacingNew] = useState(false);
  const [editingSpot, setEditingSpot] = useState(null); // spot object being renamed/positioned
  const [addonOpen, setAddonOpen] = useState(false); // whether the "Add on" group is expanded
  const [activeAddonSpot, setActiveAddonSpot] = useState(null); // add-on person being evaluated
  const [addingAddonName, setAddingAddonName] = useState(false); // adding a new add-on person
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);
  const [confirmResetId, setConfirmResetId] = useState(null);
  const [draggingId, setDraggingId] = useState(null);
  const [editingTimes, setEditingTimes] = useState(false);
  const mapRef = useRef(null);

  const currentSlots = timeSlots[viewDayType] || [];

  const zone = ZONES.find((z) => z.id === zoneId);
  // Which layout the current zone + day type + round uses. Spots live in exactly one
  // mapGroup, so only the pins belonging to this round are shown or moved.
  const currentSlotLabel = slotLabelOf(timeSlots, viewDayType, slotIdx);
  const mapGroup = getMapGroup(zoneId, currentSlotLabel, viewDayType);
  const floorImg = getFloorImg(zoneId, currentSlotLabel, viewDayType);
  const zoneSpots = spotsConfig.filter((s) => s.zone === zoneId && (s.mapGroup ? s.mapGroup === mapGroup : true));
  // "Add on" spots aren't tied to any zone/mapGroup/day type — they show under every zone,
  // weekday or weekend, as their own list below the regular spot list.
  const addonSpots = spotsConfig.filter((s) => s.zone === "addon");

  const zoneStats = useMemo(() => {
    let done = 0;
    zoneSpots.forEach((s) => {
      if (checks[s.id]?.[slotIdx]?.status) done++;
    });
    return { done, total: zoneSpots.length };
  }, [checks, zoneSpots, slotIdx]);

  const spotData = (id) => checks[id]?.[slotIdx] || null;

  const handleSave = (spotId, data, applyScope = "round") => {
    const ts = Date.now();
    if (applyScope === "round") {
      const next = { ...checks, [spotId]: { ...(checks[spotId] || {}), [slotIdx]: { ...data, ts } } };
      saveChecks(next);
    } else {
      // "all" — copy this check data to every round of the currently viewed day type
      const allSlots = { ...(checks[spotId] || {}) };
      currentSlots.forEach((_, i) => { allSlots[i] = { ...data, ts }; });
      const next = { ...checks, [spotId]: allSlots };
      saveChecks(next);
    }
    setActiveSpot(null);
  };

  const resetSpotCheck = (spotId) => {
    const spotChecks = { ...(checks[spotId] || {}) };
    delete spotChecks[slotIdx];
    const next = { ...checks, [spotId]: spotChecks };
    saveChecks(next);
    setConfirmResetId(null);
    setActiveSpot(null);
  };

  useEffect(() => {
    if (slotIdx > currentSlots.length - 1) setSlotIdx(Math.max(0, currentSlots.length - 1));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentSlots.length]);

  useEffect(() => {
    setPlacingNew(false);
    setEditingSpot(null);
    setActiveSpot(null);
    setSlotIdx(viewDayType === todayDayType && latestSlotIdx >= 0 ? latestSlotIdx : 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewDayType]);

  const pctFromEvent = (clientX, clientY) => {
    const rect = mapRef.current.getBoundingClientRect();
    let x = ((clientX - rect.left) / rect.width) * 100;
    let y = ((clientY - rect.top) / rect.height) * 100;
    x = Math.max(2, Math.min(98, x));
    y = Math.max(2, Math.min(98, y));
    return { x, y };
  };

  const handleMapTap = (e) => {
    if (!editMode || !placingNew) return;
    const touch = e.changedTouches ? e.changedTouches[0] : e;
    const { x, y } = pctFromEvent(touch.clientX, touch.clientY);
    const rx = Math.round(x * 100) / 100;
    const ry = Math.round(y * 100) / 100;
    // Tie the new pin to the layout on screen so it only appears in this round.
    const newSpot = {
      id: `spot_${Date.now()}`,
      label: "New spot",
      zone: zoneId,
      mapGroup,
      x: rx,
      y: ry,
    };
    saveSpotsConfig([...spotsConfig, newSpot]);
    setPlacingNew(false);
    setEditingSpot(newSpot);
  };

  // Dragging a pin always repositions it for the currently viewed day type + round only —
  // every other round/day type keeps its own independent position untouched. There is no
  // way to broaden a position to other rounds anymore, since each time slot's spots are
  // laid out differently and edits must never leak across rounds.
  // The dragged pin belongs only to this round's mapGroup, so writing x/y directly can
  // never disturb the layout of any other round or day type.
  const updateSpotPosition = (id, x, y) => {
    saveSpotsConfig(spotsConfig.map((s) => (s.id === id ? { ...s, x, y } : s)));
  };

  const renameSpot = (id, label) => {
    const next = spotsConfig.map((s) => (s.id === id ? { ...s, label } : s));
    saveSpotsConfig(next);
  };

  const deleteSpot = (id) => {
    saveSpotsConfig(spotsConfig.filter((s) => s.id !== id));
    setConfirmDeleteId(null);
    if (editingSpot?.id === id) setEditingSpot(null);
  };

  const addTimeSlot = () => {
    const next = [...currentSlots, "12:00"].sort();
    saveTimeSlots({ ...timeSlots, [viewDayType]: next });
  };

  const updateTimeSlot = (idx, value) => {
    const next = currentSlots.map((t, i) => (i === idx ? value : t));
    saveTimeSlots({ ...timeSlots, [viewDayType]: next });
  };

  const removeTimeSlot = (idx) => {
    if (currentSlots.length <= 1) return; // keep at least 1 slot
    const next = currentSlots.filter((_, i) => i !== idx);
    saveTimeSlots({ ...timeSlots, [viewDayType]: next });
  };

  // Drag handlers (pointer events cover both mouse + touch)
  const onPinPointerDown = (spot) => (e) => {
    if (!editMode) return;
    e.stopPropagation();
    e.preventDefault();
    setDraggingId(spot.id);
  };

  useEffect(() => {
    if (!draggingId) return;
    const onMove = (e) => {
      if (!mapRef.current) return;
      const point = e.touches ? e.touches[0] : e;
      const { x, y } = pctFromEvent(point.clientX, point.clientY);
      updateSpotPosition(draggingId, x, y);
    };
    const onUp = () => setDraggingId(null);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseup", onUp);
    window.addEventListener("touchmove", onMove, { passive: false });
    window.addEventListener("touchend", onUp);
    return () => {
      window.removeEventListener("mousemove", onMove);
      window.removeEventListener("mouseup", onUp);
      window.removeEventListener("touchmove", onMove);
      window.removeEventListener("touchend", onUp);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [draggingId, spotsConfig, viewDayType, slotIdx]);

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
      {/* Weekday / Weekend tabs */}
      <div style={{ display: "flex", gap: 7 }}>
        {[{ id: "weekday", name: "Weekday" }, { id: "weekend", name: "Weekend" }].map((d) => (
          <button
            key={d.id}
            onClick={() => { setViewDayType(d.id); setEditMode(false); }}
            style={{
              flex: 1, padding: "9px 4px", borderRadius: 10, border: "1.5px solid",
              borderColor: viewDayType === d.id ? "#2E7D32" : "#E5E7EB",
              background: viewDayType === d.id ? "#2E7D32" : "#fff",
              color: viewDayType === d.id ? "#fff" : "#374151",
              fontSize: 12.5, fontWeight: 700, display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            }}
          >
            {d.name}
            {d.id === todayDayType && (
              <span
                style={{
                  fontSize: 9, fontWeight: 800, padding: "1px 6px", borderRadius: 20,
                  background: viewDayType === d.id ? "rgba(255,255,255,0.25)" : "#EAF2FA",
                  color: viewDayType === d.id ? "#fff" : "#0058A3",
                }}
              >
                Today
              </span>
            )}
          </button>
        ))}
      </div>

      {!isLive && (
        <div style={{ fontSize: 11, color: "#9A6B00", background: "#FFF6E0", border: "1px solid #FCE3A6", borderRadius: 9, padding: "8px 10px", lineHeight: 1.4 }}>
          You're previewing the {viewDayType} layout ahead of time. Availability checks can only be logged on the {todayDayType} tab today — this tab is for adjusting spots and check rounds.
        </div>
      )}

      {/* Zone tabs */}
      <div style={{ display: "flex", gap: 7 }}>
        {ZONES.map((z) => (
          <button
            key={z.id}
            onClick={() => { setZoneId(z.id); setPlacingNew(false); }}
            style={{
              flex: 1, padding: "9px 4px", borderRadius: 10, border: "1.5px solid",
              borderColor: zoneId === z.id ? "#0058A3" : "#E5E7EB",
              background: zoneId === z.id ? "#0058A3" : "#fff",
              color: zoneId === z.id ? "#fff" : "#374151",
              fontSize: 12.5, fontWeight: 700,
            }}
          >
            {z.name}
          </button>
        ))}
      </div>

      {/* Time slot selector */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <span style={{ fontSize: 11.5, fontWeight: 700, color: "#6B7280" }}>Check rounds · {viewDayType}</span>
        <button
          onClick={() => setEditingTimes((v) => !v)}
          style={{
            display: "flex", alignItems: "center", gap: 4, padding: "4px 9px", borderRadius: 7,
            border: "1.5px solid", borderColor: editingTimes ? "#0058A3" : "#E5E7EB",
            background: editingTimes ? "#0058A3" : "#fff", color: editingTimes ? "#fff" : "#6B7280",
            fontSize: 10.5, fontWeight: 700,
          }}
        >
          <Icon name="edit" size={10} />
          {editingTimes ? "Done" : "Edit times"}
        </button>
      </div>

      {editingTimes ? (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, background: "#EAF2FA", border: "1px solid #CFE0EF", borderRadius: 10, padding: "10px 12px" }}>
          {currentSlots.map((t, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <input
                type="time"
                value={t}
                onChange={(e) => updateTimeSlot(i, e.target.value)}
                style={{ ...inputStyle, padding: "8px 10px", fontSize: 14, flex: 1 }}
              />
              <button
                onClick={() => removeTimeSlot(i)}
                disabled={currentSlots.length <= 1}
                style={{
                  display: "flex", alignItems: "center", justifyContent: "center",
                  width: 34, height: 34, borderRadius: 8, border: "1.5px solid #FBD5D5",
                  background: currentSlots.length <= 1 ? "#F3F4F6" : "#FDECEC",
                  color: currentSlots.length <= 1 ? "#C2C5CB" : "#D62B2B", flexShrink: 0,
                }}
              >
                <Icon name="trash" size={13} />
              </button>
            </div>
          ))}
          <button
            onClick={addTimeSlot}
            style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
              padding: "9px 10px", borderRadius: 8, border: "1.5px dashed #9CA3AF",
              color: "#0058A3", fontSize: 12.5, fontWeight: 700, marginTop: 2,
            }}
          >
            <Icon name="plus" size={13} />
            Add round
          </button>
        </div>
      ) : (
        <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 2 }}>
          {currentSlots.map((t, i) => {
            const allDoneForSlot = isLive && zoneSpots.every((s) => checks[s.id]?.[i]?.status);
            return (
              <button
                key={i}
                onClick={() => setSlotIdx(i)}
                style={{
                  flexShrink: 0, padding: "7px 12px", borderRadius: 8, border: "1.5px solid",
                  borderColor: slotIdx === i ? "#0058A3" : "#E5E7EB",
                  background: slotIdx === i ? "#EAF2FA" : "#fff",
                  color: slotIdx === i ? "#0058A3" : "#6B7280",
                  fontSize: 12, fontWeight: 700, position: "relative",
                  display: "flex", alignItems: "center", gap: 5,
                }}
              >
                {t}
                {allDoneForSlot && <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#2E7D32", display: "inline-block" }} />}
              </button>
            );
          })}
        </div>
      )}

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <span style={{ fontSize: 12, color: "#6B7280" }}>
          {zone.name} {isLive ? `· ${zoneStats.done}/${zoneStats.total} spots checked` : "· layout preview"}
        </span>
        <button
          onClick={() => { setEditMode((v) => !v); setPlacingNew(false); setEditingSpot(null); }}
          style={{
            display: "flex", alignItems: "center", gap: 5, padding: "5px 10px", borderRadius: 8,
            border: "1.5px solid", borderColor: editMode ? "#0058A3" : "#E5E7EB",
            background: editMode ? "#0058A3" : "#fff", color: editMode ? "#fff" : "#374151",
            fontSize: 11.5, fontWeight: 700,
          }}
        >
          <Icon name="edit" size={12} />
          {editMode ? "Done editing" : "Edit spots"}
        </button>
      </div>

      {editMode && (
        <div style={{ display: "flex", flexDirection: "column", gap: 6, background: "#EAF2FA", border: "1px solid #CFE0EF", borderRadius: 10, padding: "10px 12px" }}>
          <div style={{ fontSize: 11.5, color: "#0058A3", lineHeight: 1.4 }}>
            Drag a pin to move it for this {viewDayType} round only — other rounds keep their own position. Tap a pin to rename or delete it.
          </div>
          <button
            onClick={() => setPlacingNew((v) => !v)}
            style={{
              display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
              padding: "9px 10px", borderRadius: 8, border: "1.5px dashed",
              borderColor: placingNew ? "#0058A3" : "#9CA3AF",
              background: placingNew ? "#fff" : "transparent",
              color: "#0058A3", fontSize: 12.5, fontWeight: 700,
            }}
          >
            <Icon name="plus" size={13} />
            {placingNew ? "Tap on the map to place the new spot" : "Add spot"}
          </button>
        </div>
      )}

      {/* Map image with pins */}
      <div
        ref={mapRef}
        onClick={handleMapTap}
        style={{
          position: "relative", width: "100%", borderRadius: 14, overflow: "hidden",
          border: "1px solid #ECEDF0", background: "#fff",
          cursor: editMode && placingNew ? "crosshair" : "default",
          touchAction: editMode ? "none" : "auto",
        }}
      >
        <div style={{ position: "relative", width: "100%", paddingBottom: `${100 / getAspectRatio(zoneId)}%` }}>
          <img
            src={floorImg}
            alt={zone.name}
            draggable={false}
            style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", pointerEvents: "none" }}
          />
          {zoneSpots.map((s) => {
            const data = spotData(s.id);
            const status = isLive ? data?.status : undefined;
            const bg = editMode ? "#0058A3" : (status === "yes" ? "#2E7D32" : status === "no" ? "#D62B2B" : "#9CA3AF");
            const p = getSpotPos(s);
            return (
              <button
                key={s.id}
                onMouseDown={onPinPointerDown(s)}
                onTouchStart={onPinPointerDown(s)}
                onClick={(e) => {
                  e.stopPropagation();
                  if (editMode) {
                    if (draggingId) return;
                    setEditingSpot(s);
                  } else if (isLive) {
                    setActiveSpot(s);
                  }
                }}
                style={{
                  position: "absolute", left: `${p.x}%`, top: `${p.y}%`, transform: "translate(-50%, -50%)",
                  width: 26, height: 26, borderRadius: "50%", background: bg, border: "2.5px solid #fff",
                  boxShadow: "0 1px 4px rgba(0,0,0,0.3)", color: "#fff", fontSize: 11, fontWeight: 800,
                  display: "flex", alignItems: "center", justifyContent: "center", padding: 0,
                  touchAction: "none", cursor: editMode ? "grab" : (isLive ? "pointer" : "default"),
                }}
                title={s.label}
              >
                {editMode ? <Icon name="edit" size={11} /> : (status === "yes" ? <Icon name="check" size={13} /> : status === "no" ? <Icon name="x" size={13} /> : "")}
              </button>
            );
          })}
        </div>
      </div>

      {!editMode && isLive && (
        <div style={{ display: "flex", gap: 14, justifyContent: "center", fontSize: 11, color: "#6B7280" }}>
          <LegendDot color="#9CA3AF" label="Not checked" />
          <LegendDot color="#2E7D32" label="Staffed" />
          <LegendDot color="#D62B2B" label="Not staffed" />
        </div>
      )}

      {/* Spot list (tap-friendly alternative to pins) */}
      <div style={{ display: "flex", flexDirection: "column", gap: 7, marginTop: 4 }}>
        {zoneSpots.map((s) => {
          const data = spotData(s.id);
          return (
            <button
              key={s.id}
              onClick={() => (editMode ? setEditingSpot(s) : (isLive && setActiveSpot(s)))}
              style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                background: "#fff", border: "1px solid #ECEDF0", borderRadius: 10, padding: "10px 13px",
                textAlign: "left",
              }}
            >
              <div>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#15181F" }}>{s.label}</div>
                {!editMode && isLive && data?.coworker && <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 1 }}>{data.coworker}</div>}
              </div>
              {editMode ? <Icon name="edit" size={14} /> : (isLive ? <StatusBadge status={data?.status} /> : null)}
            </button>
          );
        })}
        {zoneSpots.length === 0 && (
          <div style={{ textAlign: "center", fontSize: 12.5, color: "#9CA3AF", padding: "14px 0" }}>
            No spots in this zone yet.
          </div>
        )}
      </div>

      {/* Add on — spots that aren't tied to any single zone/mapGroup, so they appear under
          every zone (Showroom/Market Hall/Self Serve) and both day types. Collapsed behind a
          single "Add on" header — the names only show once it's tapped open. Tapping a name
          opens the simplified Active Selling evaluation (AddonEvalModal), not the full
          SpotModal. In edit mode, tapping still opens the regular rename/delete modal, and an
          "Add name" button lets the roster grow or shrink over time. */}
      {addonSpots.length > 0 && (
        <div style={{ display: "flex", flexDirection: "column", gap: 7, marginTop: 4 }}>
          <button
            onClick={() => setAddonOpen((v) => !v)}
            style={{
              display: "flex", alignItems: "center", justifyContent: "space-between",
              background: "#fff", border: "1px solid #ECEDF0", borderRadius: 10, padding: "10px 13px",
              textAlign: "left",
            }}
          >
            <span style={{ fontSize: 13, fontWeight: 700, color: "#15181F" }}>Add on</span>
            <Icon name={addonOpen ? "chevronDown" : "chevronRight"} size={15} />
          </button>

          {addonOpen && (
            <div style={{ display: "flex", flexDirection: "column", gap: 7, paddingLeft: 12 }}>
              {addonSpots.map((s) => {
                const data = spotData(s.id);
                return (
                  <button
                    key={s.id}
                    onClick={() => (editMode ? setEditingSpot(s) : (isLive && setActiveAddonSpot(s)))}
                    style={{
                      display: "flex", alignItems: "center", justifyContent: "space-between",
                      background: "#fff", border: "1px solid #ECEDF0", borderRadius: 10, padding: "10px 13px",
                      textAlign: "left",
                    }}
                  >
                    <div style={{ fontSize: 13, fontWeight: 700, color: "#15181F" }}>{s.label}</div>
                    {editMode ? <Icon name="edit" size={14} /> : (isLive ? <StatusBadge status={data?.status} /> : null)}
                  </button>
                );
              })}
              {editMode && (
                <button
                  onClick={() => setAddingAddonName(true)}
                  style={{
                    display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
                    padding: "10px", borderRadius: 10, border: "1.5px dashed #9CA3AF",
                    background: "transparent", color: "#0058A3", fontSize: 13, fontWeight: 700,
                  }}
                >
                  <Icon name="plus" size={14} />
                  Add name
                </button>
              )}
            </div>
          )}
        </div>
      )}

      {activeSpot && isLive && (
        <SpotModal
          spot={activeSpot}
          slot={currentSlots[slotIdx]}
          existing={spotData(activeSpot.id)}
          onClose={() => setActiveSpot(null)}
          onSave={(data, applyScope) => handleSave(activeSpot.id, data, applyScope)}
          onResetRequest={() => setConfirmResetId(activeSpot.id)}
          sellingItems={sellingItems}
          saveSellingItems={saveSellingItems}
          roster={roster}
        />
      )}

      {activeAddonSpot && isLive && (
        <AddonEvalModal
          spot={activeAddonSpot}
          existing={spotData(activeAddonSpot.id)}
          onClose={() => setActiveAddonSpot(null)}
          onSave={(data) => { handleSave(activeAddonSpot.id, data, "round"); setActiveAddonSpot(null); }}
          sellingItems={sellingItems}
          saveSellingItems={saveSellingItems}
        />
      )}

      {addingAddonName && (
        <DutyNameEditModal
          initialName=""
          isNew
          placeholderExample="e.g. Mui Kanokwan"
          onClose={() => setAddingAddonName(false)}
          onSave={(text) => {
            const trimmed = text.trim();
            if (trimmed) {
              saveSpotsConfig([...spotsConfig, { id: `addon_${Date.now()}`, label: trimmed, zone: "addon", x: 50, y: 50 }]);
            }
            setAddingAddonName(false);
          }}
        />
      )}

      {confirmResetId && (
        <ConfirmResetModal
          label={spotsConfig.find((s) => s.id === confirmResetId)?.label || ""}
          time={currentSlots[slotIdx]}
          onCancel={() => setConfirmResetId(null)}
          onConfirm={() => resetSpotCheck(confirmResetId)}
        />
      )}

      {editingSpot && (
        <SpotEditModal
          spot={editingSpot}
          viewDayType={viewDayType}
          slotLabel={currentSlots[slotIdx]}
          onClose={() => setEditingSpot(null)}
          onRename={(label) => { renameSpot(editingSpot.id, label); setEditingSpot(null); }}
          onDeleteRequest={() => setConfirmDeleteId(editingSpot.id)}
        />
      )}

      {confirmDeleteId && (
        <ConfirmDeleteModal
          label={spotsConfig.find((s) => s.id === confirmDeleteId)?.label || ""}
          onCancel={() => setConfirmDeleteId(null)}
          onConfirm={() => deleteSpot(confirmDeleteId)}
        />
      )}
    </div>
  );
}

function SpotEditModal({ spot, viewDayType, slotLabel, onClose, onRename, onDeleteRequest }) {
  const [label, setLabel] = useState(spot.label);
  const dayLabel = viewDayType === "weekend" ? "Weekend" : "Weekday";

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", zIndex: 50,
        display: "flex", alignItems: "flex-end", justifyContent: "center",
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#fff", borderRadius: "18px 18px 0 0", width: "100%", maxWidth: 480,
          padding: "20px 18px 26px", display: "flex", flexDirection: "column", gap: 14,
        }}
      >
        <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>Edit spot</div>

        <div>
          <label style={{ fontSize: 12, fontWeight: 700, color: "#6B7280", display: "block", marginBottom: 6 }}>
            Spot name
          </label>
          <input
            value={label}
            onChange={(e) => setLabel(e.target.value)}
            style={inputStyle}
            placeholder="e.g. Bedroom (3)"
          />
        </div>

        <button
          onClick={() => label.trim() && onRename(label.trim())}
          disabled={!label.trim()}
          style={{
            padding: "12px", borderRadius: 10, border: "none",
            background: label.trim() ? "#0058A3" : "#C2C5CB", color: "#fff",
            fontSize: 14.5, fontWeight: 700,
          }}
        >
          Save
        </button>

        <div style={{ fontSize: 11, color: "#9CA3AF", lineHeight: 1.4, background: "#F4F5F7", borderRadius: 9, padding: "9px 10px" }}>
          This pin's position only applies to the {slotLabel || "current"} round on {dayLabel} — dragging it never
          moves the pin in other rounds or the other day type, since each time slot has its own layout.
        </div>

        <button
          onClick={onDeleteRequest}
          style={{
            display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
            padding: "11px", borderRadius: 10, border: "1.5px solid #FBD5D5",
            background: "#FDECEC", color: "#D62B2B", fontSize: 13.5, fontWeight: 700,
          }}
        >
          <Icon name="trash" size={14} />
          Delete spot
        </button>

        <button
          onClick={onClose}
          style={{ padding: "10px", borderRadius: 10, border: "none", background: "transparent", color: "#6B7280", fontSize: 13.5, fontWeight: 600 }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

function ConfirmDeleteModal({ label, onCancel, onConfirm }) {
  return (
    <div
      onClick={onCancel}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 60,
        display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#fff", borderRadius: 16, width: "100%", maxWidth: 360,
          padding: "20px 18px", display: "flex", flexDirection: "column", gap: 12,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ color: "#D62B2B", display: "flex" }}><Icon name="alert" size={18} /></span>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>Delete this spot?</div>
        </div>
        <div style={{ fontSize: 13, color: "#6B7280", lineHeight: 1.5 }}>
          "{label}" and all of its saved check history will be removed. This can't be undone.
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button
            onClick={onCancel}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#374151", fontSize: 13.5, fontWeight: 700 }}
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "none", background: "#D62B2B", color: "#fff", fontSize: 13.5, fontWeight: 700 }}
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}

function ConfirmResetModal({ label, time, onCancel, onConfirm }) {
  return (
    <div
      onClick={onCancel}
      style={{
        position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 110,
        display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          background: "#fff", borderRadius: 16, width: "100%", maxWidth: 360,
          padding: "20px 18px", display: "flex", flexDirection: "column", gap: 12,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <span style={{ color: "#D62B2B", display: "flex" }}><Icon name="alert" size={18} /></span>
          <div style={{ fontSize: 15, fontWeight: 800, color: "#15181F" }}>Reset this check?</div>
        </div>
        <div style={{ fontSize: 13, color: "#6B7280", lineHeight: 1.5 }}>
          The {time} check for "{label}" will be cleared and marked as not checked. This can't be undone.
        </div>
        <div style={{ display: "flex", gap: 8, marginTop: 4 }}>
          <button
            onClick={onCancel}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#374151", fontSize: 13.5, fontWeight: 700 }}
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            style={{ flex: 1, padding: "11px", borderRadius: 10, border: "none", background: "#D62B2B", color: "#fff", fontSize: 13.5, fontWeight: 700 }}
          >
            Reset
          </button>
        </div>
      </div>
    </div>
  );
}

function LegendDot({ color, label }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 5 }}>
      <span style={{ width: 9, height: 9, borderRadius: "50%", background: color, display: "inline-block" }} />
      {label}
    </div>
  );
}

function StatusBadge({ status }) {
  if (!status) return <span style={{ fontSize: 11, color: "#C2C5CB", fontWeight: 600 }}>Not checked</span>;
  if (status === "yes") return <span style={{ fontSize: 11, color: "#2E7D32", fontWeight: 700, background: "#E8F5E9", padding: "3px 9px", borderRadius: 6 }}>Staffed</span>;
  return <span style={{ fontSize: 11, color: "#D62B2B", fontWeight: 700, background: "#FDECEC", padding: "3px 9px", borderRadius: 6 }}>Not staffed</span>;
}

/* ---- helpers for multi-coworker record migration ---- */
function migrateExisting(existing) {
  // existing may be old-format (coworker: string, activeSelling: ...) or new-format (coworkers: [...])
  if (!existing) return null;
  if (existing.coworkers) return existing; // already new format
  // migrate old format
  const existingAS = existing.activeSelling;
  const verdict = existingAS ? (typeof existingAS === "string" ? existingAS : existingAS.verdict || "") : "";
  const items = (existingAS && typeof existingAS === "object" && existingAS.items) ? existingAS.items : {};
  const defaultHfb = HFB_GROUPS[0]?.id || "";
  return {
    ...existing,
    coworkers: existing.coworker ? [{
      id: "cw0",
      name: existing.coworker,
      hfbId: existing.coworkerHfb || defaultHfb,
      activeSelling: verdict ? { verdict, items } : "",
    }] : [],
  };
}

function makeBlankCoworker(roster) {
  return { id: `cw${Date.now()}`, name: "", hfbId: HFB_GROUPS[0]?.id || "", activeSelling: "", _custom: false };
}

function CoworkerBlock({
  cw, idx, isFirst, canRemove, roster,
  onChange, onRemove, status,
  sellingItems, saveSellingItems,
}) {
  const [editingSellingItems, setEditingSellingItems] = useState(false);
  const [newItemText, setNewItemText] = useState("");
  const [addingGroup, setAddingGroup] = useState(null);
  const [customName, setCustomName] = useState(false);

  const hfbRoster = (roster && roster[cw.hfbId]) || [];
  const sellingVerdict = cw.activeSelling?.verdict || (typeof cw.activeSelling === "string" ? cw.activeSelling : "");
  const sellingChecked = cw.activeSelling?.items || {};

  const setVerdict = (v) => onChange({ ...cw, activeSelling: v ? { verdict: v, items: {} } : "" });
  const setChecked = (items) => onChange({ ...cw, activeSelling: sellingVerdict ? { verdict: sellingVerdict, items } : "" });
  const toggleItem = (id) => setChecked({ ...sellingChecked, [id]: !sellingChecked[id] });

  const addItem = (group) => {
    const text = newItemText.trim();
    if (!text) return;
    const id = `s${group[0]}${Date.now()}`;
    const next = { ...sellingItems, [group]: [...(sellingItems[group] || []), { id, text }] };
    saveSellingItems(next);
    setNewItemText("");
    setAddingGroup(null);
  };
  const removeSellingItem = (group, id) => {
    const next = { ...sellingItems, [group]: sellingItems[group].filter((i) => i.id !== id) };
    saveSellingItems(next);
    setChecked((prev) => { const n = { ...prev }; delete n[id]; return n; });
  };

  return (
    <div style={{ border: "1.5px solid #E5E7EB", borderRadius: 12, padding: "12px 13px", marginBottom: 10, background: "#FAFBFC" }}>
      {/* Header row */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <span style={{ fontSize: 12, fontWeight: 800, color: "#6B7280", letterSpacing: "0.05em" }}>
          COWORKER {idx + 1}
        </span>
        {canRemove && (
          <button
            onClick={onRemove}
            style={{ display: "flex", alignItems: "center", gap: 4, border: "none", background: "#FDECEC", color: "#D62B2B", borderRadius: 7, padding: "3px 9px", fontSize: 11.5, fontWeight: 700 }}
          >
            <Icon name="trash" size={11} /> Remove
          </button>
        )}
      </div>

      {/* HFB selector */}
      <div style={{ display: "flex", gap: 8, marginBottom: 7 }}>
        <select
          value={cw.hfbId}
          onChange={(e) => { onChange({ ...cw, hfbId: e.target.value, name: "" }); setCustomName(false); }}
          style={{ ...inputStyle, fontSize: 13, flex: 1 }}
        >
          {HFB_GROUPS.map((g) => (
            <option key={g.id} value={g.id}>{g.label} ({g.hfbLabel})</option>
          ))}
        </select>
      </div>

      {/* Name picker */}
      {!customName ? (
        <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
          <select
            value={hfbRoster.some((c) => c.name === cw.name) ? cw.name : ""}
            onChange={(e) => {
              if (e.target.value === "__other__") { setCustomName(true); onChange({ ...cw, name: "" }); return; }
              onChange({ ...cw, name: e.target.value });
            }}
            style={{ ...inputStyle, flex: 1 }}
          >
            <option value="">{hfbRoster.length ? "Select coworker..." : "No coworkers in this HFB yet"}</option>
            {hfbRoster.map((c) => (<option key={c.id} value={c.name}>{c.name}</option>))}
            <option value="__other__">Other / type name...</option>
          </select>
        </div>
      ) : (
        <div style={{ display: "flex", gap: 8, marginBottom: 10 }}>
          <input
            autoFocus
            value={cw.name}
            onChange={(e) => onChange({ ...cw, name: e.target.value })}
            placeholder="Type the coworker's name"
            style={{ ...inputStyle, flex: 1 }}
          />
          <button
            onClick={() => setCustomName(false)}
            style={{ padding: "0 12px", borderRadius: 10, border: "1.5px solid #E5E7EB", background: "#fff", color: "#6B7280", fontSize: 12, fontWeight: 700, flexShrink: 0 }}
          >
            List
          </button>
        </div>
      )}
      {cw.name && !hfbRoster.some((c) => c.name === cw.name) && !customName && (
        <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: -7, marginBottom: 10 }}>
          "{cw.name}" isn't in the {HFB_GROUPS.find((g) => g.id === cw.hfbId)?.label} roster yet.
        </div>
      )}

      {/* Active Selling — only when spot is Staffed */}
      {status === "yes" && (
        <>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#6B7280" }}>
              <Icon name="spark" size={13} />
              <span style={{ fontSize: 12, fontWeight: 700 }}>Active Selling</span>
            </div>
            <button
              onClick={() => setEditingSellingItems((v) => !v)}
              style={{
                display: "flex", alignItems: "center", gap: 4, padding: "3px 8px", borderRadius: 6,
                border: "1.5px solid", borderColor: editingSellingItems ? "#0058A3" : "#E5E7EB",
                background: editingSellingItems ? "#0058A3" : "#fff", color: editingSellingItems ? "#fff" : "#6B7280",
                fontSize: 10.5, fontWeight: 700,
              }}
            >
              <Icon name="edit" size={10} />
              {editingSellingItems ? "Done" : "Edit items"}
            </button>
          </div>

          {/* YES group */}
          <div style={{ background: "#F0FAF3", borderRadius: 10, border: "1px solid #C3E6CB", padding: "10px 12px", marginBottom: 8 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <button
                onClick={() => setVerdict(sellingVerdict === "yes" ? "" : "yes")}
                style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: sellingVerdict === "yes" ? "#2E7D32" : "#9CA3AF", background: sellingVerdict === "yes" ? "#2E7D32" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
              >
                {sellingVerdict === "yes" && <Icon name="check" size={13} />}
              </button>
              <span style={{ fontSize: 13, fontWeight: 700, color: "#2E7D32" }}>Yes — actively selling</span>
            </div>
            {(sellingItems.yes || []).map((item) => (
              <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
                <button
                  onClick={() => toggleItem(item.id)}
                  disabled={sellingVerdict !== "yes"}
                  style={{ width: 20, height: 20, borderRadius: 5, border: "2px solid", borderColor: sellingChecked[item.id] ? "#2E7D32" : "#D1D5DB", background: sellingChecked[item.id] ? "#2E7D32" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: sellingVerdict !== "yes" ? 0.4 : 1 }}
                >
                  {sellingChecked[item.id] && <Icon name="check" size={11} />}
                </button>
                <span style={{ fontSize: 13, color: "#374151", flex: 1, opacity: sellingVerdict !== "yes" ? 0.5 : 1 }}>{item.text}</span>
                {editingSellingItems && (
                  <button onClick={() => removeSellingItem("yes", item.id)} style={{ border: "none", background: "transparent", color: "#D62B2B", padding: 2, display: "flex" }}><Icon name="trash" size={12} /></button>
                )}
              </div>
            ))}
            {editingSellingItems && (addingGroup === "yes" ? (
              <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
                <input autoFocus value={newItemText} onChange={(e) => setNewItemText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addItem("yes"); if (e.key === "Escape") { setAddingGroup(null); setNewItemText(""); } }} placeholder="New item..." style={{ ...inputStyle, padding: "7px 10px", fontSize: 13, flex: 1 }} />
                <button onClick={() => addItem("yes")} style={{ padding: "7px 12px", borderRadius: 8, border: "none", background: "#2E7D32", color: "#fff", fontWeight: 700, fontSize: 13 }}>Add</button>
                <button onClick={() => { setAddingGroup(null); setNewItemText(""); }} style={{ padding: "7px 10px", borderRadius: 8, border: "none", background: "#E5E7EB", color: "#6B7280", fontSize: 13 }}>✕</button>
              </div>
            ) : (
              <button onClick={() => { setAddingGroup("yes"); setNewItemText(""); }} style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "transparent", border: "none", color: "#2E7D32", fontSize: 12.5, fontWeight: 700, padding: 0 }}>
                <Icon name="plus" size={12} /> Add item
              </button>
            ))}
          </div>

          {/* NO group */}
          <div style={{ background: "#FEF2F2", borderRadius: 10, border: "1px solid #FECACA", padding: "10px 12px", marginBottom: 8 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <button
                onClick={() => setVerdict(sellingVerdict === "no" ? "" : "no")}
                style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: sellingVerdict === "no" ? "#D62B2B" : "#9CA3AF", background: sellingVerdict === "no" ? "#D62B2B" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
              >
                {sellingVerdict === "no" && <Icon name="check" size={13} />}
              </button>
              <span style={{ fontSize: 13, fontWeight: 700, color: "#D62B2B" }}>No — not actively selling</span>
            </div>
            {(sellingItems.no || []).map((item) => (
              <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
                <button
                  onClick={() => toggleItem(item.id)}
                  disabled={sellingVerdict !== "no"}
                  style={{ width: 20, height: 20, borderRadius: 5, border: "2px solid", borderColor: sellingChecked[item.id] ? "#D62B2B" : "#D1D5DB", background: sellingChecked[item.id] ? "#D62B2B" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: sellingVerdict !== "no" ? 0.4 : 1 }}
                >
                  {sellingChecked[item.id] && <Icon name="check" size={11} />}
                </button>
                <span style={{ fontSize: 13, color: "#374151", flex: 1, opacity: sellingVerdict !== "no" ? 0.5 : 1 }}>{item.text}</span>
                {editingSellingItems && (
                  <button onClick={() => removeSellingItem("no", item.id)} style={{ border: "none", background: "transparent", color: "#D62B2B", padding: 2, display: "flex" }}><Icon name="trash" size={12} /></button>
                )}
              </div>
            ))}
            {editingSellingItems && (addingGroup === "no" ? (
              <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
                <input autoFocus value={newItemText} onChange={(e) => setNewItemText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addItem("no"); if (e.key === "Escape") { setAddingGroup(null); setNewItemText(""); } }} placeholder="New item..." style={{ ...inputStyle, padding: "7px 10px", fontSize: 13, flex: 1 }} />
                <button onClick={() => addItem("no")} style={{ padding: "7px 12px", borderRadius: 8, border: "none", background: "#D62B2B", color: "#fff", fontWeight: 700, fontSize: 13 }}>Add</button>
                <button onClick={() => { setAddingGroup(null); setNewItemText(""); }} style={{ padding: "7px 10px", borderRadius: 8, border: "none", background: "#E5E7EB", color: "#6B7280", fontSize: 13 }}>✕</button>
              </div>
            ) : (
              <button onClick={() => { setAddingGroup("no"); setNewItemText(""); }} style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "transparent", border: "none", color: "#D62B2B", fontSize: 12.5, fontWeight: 700, padding: 0 }}>
                <Icon name="plus" size={12} /> Add item
              </button>
            ))}
          </div>

          {/* NO CUSTOMER */}
          <div style={{ background: "#F4F5F7", borderRadius: 10, border: "1px solid #E0E2E6", padding: "10px 12px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <button
                onClick={() => setVerdict(sellingVerdict === "nocustomer" ? "" : "nocustomer")}
                style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: sellingVerdict === "nocustomer" ? "#6B7280" : "#9CA3AF", background: sellingVerdict === "nocustomer" ? "#6B7280" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
              >
                {sellingVerdict === "nocustomer" && <Icon name="check" size={13} />}
              </button>
              <span style={{ fontSize: 13, fontWeight: 700, color: "#6B7280" }}>No customer</span>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

// Evaluation modal for the "Add on" roster — only the Active Selling section (same Yes/No
// groups and shared, editable item lists as a regular spot's coworker block) plus a comment.
// No Coworker Availability toggle, no HFB/name picker, no round-scope choice — this modal
// shows exactly what's needed to evaluate one person and nothing else.
function AddonEvalModal({ spot, existing, onClose, onSave, sellingItems, saveSellingItems }) {
  const [editingSellingItems, setEditingSellingItems] = useState(false);
  const [newItemText, setNewItemText] = useState("");
  const [addingGroup, setAddingGroup] = useState(null);
  const [verdict, setVerdictState] = useState(existing?.activeSelling?.verdict || "");
  const [checkedItems, setCheckedItems] = useState(existing?.activeSelling?.items || {});
  const [comment, setComment] = useState(existing?.comment || "");

  const setVerdict = (v) => {
    const next = v === verdict ? "" : v;
    setVerdictState(next);
    setCheckedItems({});
  };
  const toggleItem = (id) => setCheckedItems((prev) => ({ ...prev, [id]: !prev[id] }));

  const addItem = (group) => {
    const text = newItemText.trim();
    if (!text) return;
    const id = `s${group[0]}${Date.now()}`;
    const next = { ...sellingItems, [group]: [...(sellingItems[group] || []), { id, text }] };
    saveSellingItems(next);
    setNewItemText("");
    setAddingGroup(null);
  };
  const removeSellingItem = (group, id) => {
    const next = { ...sellingItems, [group]: sellingItems[group].filter((i) => i.id !== id) };
    saveSellingItems(next);
    setCheckedItems((prev) => { const n = { ...prev }; delete n[id]; return n; });
  };

  const canSave = !!verdict;

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 100, display: "flex", alignItems: "flex-end" }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{ background: "#fff", width: "100%", maxWidth: 720, margin: "0 auto", borderRadius: "18px 18px 0 0", padding: "18px 18px 22px", maxHeight: "90vh", overflowY: "auto" }}
      >
        <div style={{ width: 38, height: 4, background: "#E5E7EB", borderRadius: 2, margin: "0 auto 14px" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
          <div style={{ fontSize: 16.5, fontWeight: 800 }}>{spot.label}</div>
          <button onClick={onClose} style={{ border: "none", background: "#F4F5F7", borderRadius: "50%", width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", color: "#6B7280" }}>
            <Icon name="x" size={15} />
          </button>
        </div>

        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 8 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, color: "#6B7280" }}>
            <Icon name="spark" size={13} />
            <span style={{ fontSize: 12, fontWeight: 700 }}>Active Selling</span>
          </div>
          <button
            onClick={() => setEditingSellingItems((v) => !v)}
            style={{
              display: "flex", alignItems: "center", gap: 4, padding: "3px 8px", borderRadius: 6,
              border: "1.5px solid", borderColor: editingSellingItems ? "#0058A3" : "#E5E7EB",
              background: editingSellingItems ? "#0058A3" : "#fff", color: editingSellingItems ? "#fff" : "#6B7280",
              fontSize: 10.5, fontWeight: 700,
            }}
          >
            <Icon name="edit" size={10} />
            {editingSellingItems ? "Done" : "Edit items"}
          </button>
        </div>

        {/* YES group */}
        <div style={{ background: "#F0FAF3", borderRadius: 10, border: "1px solid #C3E6CB", padding: "10px 12px", marginBottom: 8 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
            <button
              onClick={() => setVerdict("yes")}
              style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: verdict === "yes" ? "#2E7D32" : "#9CA3AF", background: verdict === "yes" ? "#2E7D32" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
            >
              {verdict === "yes" && <Icon name="check" size={13} />}
            </button>
            <span style={{ fontSize: 13, fontWeight: 700, color: "#2E7D32" }}>Yes — actively selling</span>
          </div>
          {(sellingItems.yes || []).map((item) => (
            <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
              <button
                onClick={() => toggleItem(item.id)}
                disabled={verdict !== "yes"}
                style={{ width: 20, height: 20, borderRadius: 5, border: "2px solid", borderColor: checkedItems[item.id] ? "#2E7D32" : "#D1D5DB", background: checkedItems[item.id] ? "#2E7D32" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: verdict !== "yes" ? 0.4 : 1 }}
              >
                {checkedItems[item.id] && <Icon name="check" size={11} />}
              </button>
              <span style={{ fontSize: 13, color: "#374151", flex: 1, opacity: verdict !== "yes" ? 0.5 : 1 }}>{item.text}</span>
              {editingSellingItems && (
                <button onClick={() => removeSellingItem("yes", item.id)} style={{ border: "none", background: "transparent", color: "#D62B2B", padding: 2, display: "flex" }}><Icon name="trash" size={12} /></button>
              )}
            </div>
          ))}
          {editingSellingItems && (addingGroup === "yes" ? (
            <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
              <input autoFocus value={newItemText} onChange={(e) => setNewItemText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addItem("yes"); if (e.key === "Escape") { setAddingGroup(null); setNewItemText(""); } }} placeholder="New item..." style={{ ...inputStyle, padding: "7px 10px", fontSize: 13, flex: 1 }} />
              <button onClick={() => addItem("yes")} style={{ padding: "7px 12px", borderRadius: 8, border: "none", background: "#2E7D32", color: "#fff", fontWeight: 700, fontSize: 13 }}>Add</button>
              <button onClick={() => { setAddingGroup(null); setNewItemText(""); }} style={{ padding: "7px 10px", borderRadius: 8, border: "none", background: "#E5E7EB", color: "#6B7280", fontSize: 13 }}>✕</button>
            </div>
          ) : (
            <button onClick={() => { setAddingGroup("yes"); setNewItemText(""); }} style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "transparent", border: "none", color: "#2E7D32", fontSize: 12.5, fontWeight: 700, padding: 0 }}>
              <Icon name="plus" size={12} /> Add item
            </button>
          ))}
        </div>

        {/* NO group */}
        <div style={{ background: "#FEF2F2", borderRadius: 10, border: "1px solid #FECACA", padding: "10px 12px", marginBottom: 8 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
            <button
              onClick={() => setVerdict("no")}
              style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: verdict === "no" ? "#D62B2B" : "#9CA3AF", background: verdict === "no" ? "#D62B2B" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
            >
              {verdict === "no" && <Icon name="check" size={13} />}
            </button>
            <span style={{ fontSize: 13, fontWeight: 700, color: "#D62B2B" }}>No — not actively selling</span>
          </div>
          {(sellingItems.no || []).map((item) => (
            <div key={item.id} style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 7 }}>
              <button
                onClick={() => toggleItem(item.id)}
                disabled={verdict !== "no"}
                style={{ width: 20, height: 20, borderRadius: 5, border: "2px solid", borderColor: checkedItems[item.id] ? "#D62B2B" : "#D1D5DB", background: checkedItems[item.id] ? "#D62B2B" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, opacity: verdict !== "no" ? 0.4 : 1 }}
              >
                {checkedItems[item.id] && <Icon name="check" size={11} />}
              </button>
              <span style={{ fontSize: 13, color: "#374151", flex: 1, opacity: verdict !== "no" ? 0.5 : 1 }}>{item.text}</span>
              {editingSellingItems && (
                <button onClick={() => removeSellingItem("no", item.id)} style={{ border: "none", background: "transparent", color: "#D62B2B", padding: 2, display: "flex" }}><Icon name="trash" size={12} /></button>
              )}
            </div>
          ))}
          {editingSellingItems && (addingGroup === "no" ? (
            <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
              <input autoFocus value={newItemText} onChange={(e) => setNewItemText(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") addItem("no"); if (e.key === "Escape") { setAddingGroup(null); setNewItemText(""); } }} placeholder="New item..." style={{ ...inputStyle, padding: "7px 10px", fontSize: 13, flex: 1 }} />
              <button onClick={() => addItem("no")} style={{ padding: "7px 12px", borderRadius: 8, border: "none", background: "#D62B2B", color: "#fff", fontWeight: 700, fontSize: 13 }}>Add</button>
              <button onClick={() => { setAddingGroup(null); setNewItemText(""); }} style={{ padding: "7px 10px", borderRadius: 8, border: "none", background: "#E5E7EB", color: "#6B7280", fontSize: 13 }}>✕</button>
            </div>
          ) : (
            <button onClick={() => { setAddingGroup("no"); setNewItemText(""); }} style={{ display: "flex", alignItems: "center", gap: 5, marginTop: 6, background: "transparent", border: "none", color: "#D62B2B", fontSize: 12.5, fontWeight: 700, padding: 0 }}>
              <Icon name="plus" size={12} /> Add item
            </button>
          ))}
        </div>

        {/* NO CUSTOMER */}
        <div style={{ background: "#F4F5F7", borderRadius: 10, border: "1px solid #E0E2E6", padding: "10px 12px", marginBottom: 18 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <button
              onClick={() => setVerdict("nocustomer")}
              style={{ width: 22, height: 22, borderRadius: 6, border: "2px solid", borderColor: verdict === "nocustomer" ? "#6B7280" : "#9CA3AF", background: verdict === "nocustomer" ? "#6B7280" : "#fff", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}
            >
              {verdict === "nocustomer" && <Icon name="check" size={13} />}
            </button>
            <span style={{ fontSize: 13, fontWeight: 700, color: "#6B7280" }}>No customer</span>
          </div>
        </div>

        <FieldLabel icon="list" text="Comment (optional)" />
        <textarea
          value={comment}
          onChange={(e) => setComment(e.target.value)}
          placeholder="Add a note..."
          rows={2}
          style={{ ...inputStyle, fontWeight: 400, fontSize: 13.5, resize: "vertical", marginBottom: 18 }}
        />

        <button
          disabled={!canSave}
          onClick={() => onSave({ status: verdict === "yes" ? "yes" : "no", activeSelling: { verdict, items: checkedItems }, comment })}
          style={{ width: "100%", padding: "13px", borderRadius: 11, border: "none", background: canSave ? "#0058A3" : "#D1D5DB", color: "#fff", fontSize: 14.5, fontWeight: 700 }}
        >
          Save
        </button>
      </div>
    </div>
  );
}

function SpotModal({ spot, slot, existing, onClose, onSave, onResetRequest, sellingItems, saveSellingItems, roster }) {
  const migrated = migrateExisting(existing);
  const defaultHfb = (() => { const g = findHfbGroupForSpot(spot); return g ? g.id : (HFB_GROUPS[0]?.id || ""); })();

  const [status, setStatus] = useState(migrated?.status || "");
  const [coworkers, setCoworkers] = useState(
    migrated?.coworkers?.length
      ? migrated.coworkers
      : [{ id: "cw0", name: "", hfbId: defaultHfb, activeSelling: "" }]
  );
  const [comment, setComment] = useState(migrated?.comment || "");
  const [applyAll, setApplyAll] = useState(false);

  const updateCoworker = (idx, cw) => setCoworkers((prev) => prev.map((c, i) => (i === idx ? cw : c)));
  const addCoworker = () => setCoworkers((prev) => [...prev, { id: `cw${Date.now()}`, name: "", hfbId: defaultHfb, activeSelling: "" }]);
  const removeCoworker = (idx) => setCoworkers((prev) => prev.filter((_, i) => i !== idx));

  // primary coworker name for display on map list
  const primaryName = coworkers[0]?.name || "";

  return (
    <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", zIndex: 100, display: "flex", alignItems: "flex-end" }} onClick={onClose}>
      <div
        onClick={(e) => e.stopPropagation()}
        style={{ background: "#fff", width: "100%", maxWidth: 720, margin: "0 auto", borderRadius: "18px 18px 0 0", padding: "18px 18px 22px", maxHeight: "90vh", overflowY: "auto" }}
      >
        <div style={{ width: 38, height: 4, background: "#E5E7EB", borderRadius: 2, margin: "0 auto 14px" }} />
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 16 }}>
          <div>
            <div style={{ fontSize: 16.5, fontWeight: 800 }}>{spot.label}</div>
            <div style={{ fontSize: 12, color: "#9CA3AF", marginTop: 2 }}>{slot} round</div>
          </div>
          <button onClick={onClose} style={{ border: "none", background: "#F4F5F7", borderRadius: "50%", width: 30, height: 30, display: "flex", alignItems: "center", justifyContent: "center", color: "#6B7280" }}>
            <Icon name="x" size={15} />
          </button>
        </div>

        {/* Coworker Availability — spot level, one toggle */}
        <FieldLabel icon="users" text="Coworker Availability" />
        <div style={{ display: "flex", gap: 8, marginBottom: 18 }}>
          <ToggleBtn active={status === "yes"} onClick={() => setStatus("yes")} color="#2E7D32" label="Staffed" />
          <ToggleBtn
            active={status === "no"}
            onClick={() => { setStatus("no"); setCoworkers((prev) => prev.map((c) => ({ ...c, activeSelling: "" }))); }}
            color="#D62B2B"
            label="Not staffed"
          />
        </div>

        {/* Multi-coworker blocks */}
        <FieldLabel icon="users" text={`Coworker${coworkers.length > 1 ? "s" : ""} in this spot`} />
        {coworkers.map((cw, idx) => (
          <CoworkerBlock
            key={cw.id}
            cw={cw}
            idx={idx}
            isFirst={idx === 0}
            canRemove={coworkers.length > 1}
            roster={roster}
            status={status}
            sellingItems={sellingItems}
            saveSellingItems={saveSellingItems}
            onChange={(updated) => updateCoworker(idx, updated)}
            onRemove={() => removeCoworker(idx)}
          />
        ))}

        {/* Add coworker button */}
        <button
          onClick={addCoworker}
          style={{
            width: "100%", display: "flex", alignItems: "center", justifyContent: "center", gap: 7,
            padding: "10px", borderRadius: 10, border: "1.5px dashed #9CA3AF",
            background: "transparent", color: "#0058A3", fontSize: 13, fontWeight: 700, marginBottom: 16,
          }}
        >
          <Icon name="plus" size={14} />
          Add another coworker in this spot
        </button>

        <FieldLabel icon="list" text="Comment (optional)" />
        <textarea
          value={comment}
          onChange={(e) => setComment(e.target.value)}
          placeholder="Add a note..."
          rows={2}
          style={{ ...inputStyle, fontWeight: 400, fontSize: 13.5, resize: "vertical", marginBottom: 18 }}
        />

        <div style={{ display: "flex", gap: 6, marginBottom: 12 }}>
          <button
            onClick={() => setApplyAll(false)}
            style={{ flex: 1, padding: "9px 6px", borderRadius: 9, border: "1.5px solid", borderColor: !applyAll ? "#0058A3" : "#E5E7EB", background: !applyAll ? "#EAF2FA" : "#fff", color: !applyAll ? "#0058A3" : "#6B7280", fontSize: 12, fontWeight: 700 }}
          >
            This round only
          </button>
          <button
            onClick={() => setApplyAll(true)}
            style={{ flex: 1, padding: "9px 6px", borderRadius: 9, border: "1.5px solid", borderColor: applyAll ? "#0058A3" : "#E5E7EB", background: applyAll ? "#0058A3" : "#fff", color: applyAll ? "#fff" : "#6B7280", fontSize: 12, fontWeight: 700 }}
          >
            Apply to all rounds
          </button>
        </div>

        <button
          disabled={!status}
          onClick={() => onSave({ status, coworker: primaryName, coworkers, comment }, applyAll ? "all" : "round")}
          style={{ width: "100%", padding: "13px", borderRadius: 11, border: "none", background: status ? "#0058A3" : "#D1D5DB", color: "#fff", fontSize: 14.5, fontWeight: 700 }}
        >
          {applyAll ? "Save to all rounds" : `Save — ${slot}`}
        </button>

        {existing && (
          <button
            onClick={onResetRequest}
            style={{ width: "100%", padding: "11px", borderRadius: 11, border: "1.5px solid #FBD5D5", background: "#FDECEC", color: "#D62B2B", fontSize: 13.5, fontWeight: 700, marginTop: 9, display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
          >
            <Icon name="trash" size={13} />
            Reset this check
          </button>
        )}
      </div>
    </div>
  );
}

function ToggleBtn({ active, onClick, color, label }) {
  return (
    <button
      onClick={onClick}
      style={{
        flex: 1, padding: "11px 8px", borderRadius: 10, border: "1.5px solid",
        borderColor: active ? color : "#E5E7EB", background: active ? color : "#fff",
        color: active ? "#fff" : "#6B7280", fontSize: 13, fontWeight: 700,
      }}
    >
      {label}
    </button>
  );
}

/* ===================== CHECKLIST VIEW ===================== */
// Groups the 7 checklist sections under 4 time-of-day tabs so the list matches how the
// routine is actually worked through during a shift.
const CHECKLIST_PERIODS = [
  { id: "before10", label: "Before 10:00", sections: ["morning_before10", "morning_media"] },
  { id: "roomsetting", label: "Showroom & Markethall before 10:00", sections: ["showroom", "markethall"] },
  { id: "after10", label: "After 10:00", sections: ["morning_after10", "pm_after10"] },
  { id: "after2130", label: "After 21:30", sections: ["after2130"] },
];

function ChecklistView({ fn, checklist, saveChecklist, checklistItems, saveChecklistItems, sectionTitles, saveSectionTitles }) {
  const isSales = !fn || fn.hasMap;
  const [editMode, setEditMode] = useState(false);
  const [draftText, setDraftText] = useState({});
  const [titleDraft, setTitleDraft] = useState({});
  const [itemDraft, setItemDraft] = useState({});
  const [drag, setDrag] = useState(null);
  const listRefs = useRef({});

  // Sales has a fixed routine split across time-of-day periods. Other functions have a single
  // user-built list, so their sections come from whatever keys exist in checklistItems, all
  // shown together under one period.
  const salesSections = [
    { key: "morning_before10", defaultTitle: "Before store open", color: "#0058A3" },
    { key: "morning_media", defaultTitle: "Media and Add-on with 4 Basics", color: "#0058A3" },
    { key: "showroom", defaultTitle: "Showroom — Roomsetting Basic Review (4 Basics, Maintain roomsetting)", color: "#2E7D32" },
    { key: "markethall", defaultTitle: "Markethall — Replenishment", color: "#2E7D32" },
    { key: "morning_after10", defaultTitle: "AM Commercial walk 10:00/12:00/14:00", color: "#2E7D32" },
    { key: "pm_after10", defaultTitle: "PM Commercial walk 16:00/18:00/20:00", color: "#2E7D32" },
    { key: "afternoon", defaultTitle: "Afternoon Sales Duty (15:30 / 18:30 / 19:30)", color: "#B8590B" },
    { key: "after2130", defaultTitle: "After 21:30", color: "#B8590B" },
  ];

  const otherSections = Object.keys(checklistItems).map((key) => ({
    key,
    defaultTitle: sectionTitles[key] || "Checklist",
    color: "#0058A3",
  }));

  const sections = isSales ? salesSections : otherSections;
  const periods = isSales
    ? CHECKLIST_PERIODS
    : [{ id: "all", label: "Checklist", sections: otherSections.map((s) => s.key) }];

  const [periodId, setPeriodId] = useState(periods[0].id);
  const activePeriod = periods.find((p) => p.id === periodId) || periods[0];
  const visibleSections = sections.filter((s) => activePeriod.sections.includes(s.key));

  // Progress per tab, shown as a badge so it's clear at a glance which time-of-day block
  // still has open items.
  const periodProgress = (period) => {
    let done = 0, total = 0;
    period.sections.forEach((key) => {
      const items = checklistItems[key] || [];
      total += items.length;
      done += items.filter((it) => checklist[key]?.[it.id]).length;
    });
    return { done, total };
  };

  const commitTitle = (key) => {
    const val = (titleDraft[key] ?? sectionTitles[key] ?? "").trim();
    if (!val) return;
    saveSectionTitles({ ...sectionTitles, [key]: val });
  };

  const toggle = (sectionKey, itemId) => {
    const next = {
      ...checklist,
      [sectionKey]: { ...(checklist[sectionKey] || {}), [itemId]: !checklist[sectionKey]?.[itemId] },
    };
    saveChecklist(next);
  };

  const addItem = (sectionKey) => {
    const text = (draftText[sectionKey] || "").trim();
    if (!text) return;
    const newId = `${sectionKey[0]}_${Date.now()}`;
    const next = {
      ...checklistItems,
      [sectionKey]: [...(checklistItems[sectionKey] || []), { id: newId, text }],
    };
    saveChecklistItems(next);
    setDraftText({ ...draftText, [sectionKey]: "" });
  };

  const removeItem = (sectionKey, itemId) => {
    const next = {
      ...checklistItems,
      [sectionKey]: (checklistItems[sectionKey] || []).filter((it) => it.id !== itemId),
    };
    saveChecklistItems(next);
  };

  // Rename an existing item. Blank text is ignored so an accidental clear can't wipe a row —
  // deleting is done deliberately with the trash button instead.
  const renameItem = (sectionKey, itemId, text) => {
    const val = (text || "").trim();
    if (!val) return;
    const list = checklistItems[sectionKey] || [];
    if (list.some((it) => it.id === itemId && it.text === val)) return;
    saveChecklistItems({
      ...checklistItems,
      [sectionKey]: list.map((it) => (it.id === itemId ? { ...it, text: val } : it)),
    });
  };

  // Drag-to-reorder. Rows are measured once when the drag starts and then treated as fixed
  // slots, so the target index is just "which slot is the finger over" — that stays stable
  // even while the list re-renders in its previewed order underneath.
  const startDrag = (e, sectionKey, index) => {
    const container = listRefs.current[sectionKey];
    if (!container) return;
    const rects = Array.from(container.querySelectorAll("[data-row]")).map((r) => {
      const b = r.getBoundingClientRect();
      return { top: b.top, height: b.height };
    });
    if (e.currentTarget.setPointerCapture) {
      try { e.currentTarget.setPointerCapture(e.pointerId); } catch { /* older browsers */ }
    }
    setDrag({ sectionKey, from: index, to: index, rects });
  };

  const onDragMove = (e) => {
    if (!drag) return;
    const y = e.clientY;
    const { rects } = drag;
    let to = rects.length - 1;
    for (let i = 0; i < rects.length; i++) {
      if (y < rects[i].top + rects[i].height / 2) { to = i; break; }
    }
    if (to !== drag.to) setDrag({ ...drag, to });
  };

  const endDrag = () => {
    if (!drag) return;
    const { sectionKey, from, to } = drag;
    setDrag(null);
    if (from === to) return;
    const list = [...(checklistItems[sectionKey] || [])];
    const [moved] = list.splice(from, 1);
    list.splice(to, 0, moved);
    saveChecklistItems({ ...checklistItems, [sectionKey]: list });
  };

  // While a drag is in progress the section renders in its provisional order, so the row
  // visibly follows the finger before anything is committed.
  const displayItems = (sectionKey, items) => {
    if (!drag || drag.sectionKey !== sectionKey) return items;
    const list = [...items];
    const [moved] = list.splice(drag.from, 1);
    list.splice(drag.to, 0, moved);
    return list;
  };

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {/* Time-of-day tabs (Sales only has several; other functions have a single list, so the
          row is hidden for them). */}
      {periods.length > 1 && (
      <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 2 }}>
        {periods.map((p) => {
          const prog = periodProgress(p);
          const complete = prog.total > 0 && prog.done === prog.total;
          return (
            <button
              key={p.id}
              onClick={() => setPeriodId(p.id)}
              style={{
                flexShrink: 0, minWidth: 110, textAlign: "left", padding: "9px 12px", borderRadius: 10, border: "1.5px solid",
                borderColor: periodId === p.id ? "#0058A3" : "#E5E7EB",
                background: periodId === p.id ? "#EAF2FA" : "#fff",
              }}
            >
              <div style={{ fontSize: 11.5, fontWeight: 700, color: periodId === p.id ? "#0058A3" : "#15181F" }}>{p.label}</div>
              <div style={{ fontSize: 9.5, fontWeight: 700, marginTop: 3, color: complete ? "#2E7D32" : "#9CA3AF" }}>
                {prog.done}/{prog.total} done
              </div>
            </button>
          );
        })}
      </div>
      )}

      <button
        onClick={() => setEditMode((v) => !v)}
        style={{
          alignSelf: "flex-end", display: "flex", alignItems: "center", gap: 6, border: "1.5px solid",
          borderColor: editMode ? "#0058A3" : "#E5E7EB", background: editMode ? "#EAF2FA" : "#fff",
          color: editMode ? "#0058A3" : "#6B7280", borderRadius: 9, padding: "7px 13px", fontSize: 12.5, fontWeight: 700,
        }}
      >
        <Icon name={editMode ? "check" : "edit"} size={14} />
        {editMode ? "Done editing" : "Edit list"}
      </button>

      {editMode && (
        <div style={{ fontSize: 11.5, color: "#9CA3AF", lineHeight: 1.5, background: "#F4F5F7", borderRadius: 9, padding: "9px 11px", marginTop: -6 }}>
          Tap any line to rename it, drag the handle on the left to change its order, and use the bin to remove it.
          Changes save as soon as you tap away.
        </div>
      )}

      {visibleSections.map((sec) => {
        const items = checklistItems[sec.key] || [];
        const done = items.filter((it) => checklist[sec.key]?.[it.id]).length;
        return (
          <div key={sec.key} style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", overflow: "hidden" }}>
            <div style={{ padding: "13px 16px", borderBottom: "1px solid #F0F1F3", display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10 }}>
              {editMode ? (
                <input
                  value={titleDraft[sec.key] ?? sectionTitles[sec.key] ?? sec.defaultTitle}
                  onChange={(e) => setTitleDraft((d) => ({ ...d, [sec.key]: e.target.value }))}
                  onBlur={() => commitTitle(sec.key)}
                  onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
                  style={{ ...inputStyle, fontSize: 13.5, fontWeight: 700, padding: "6px 9px", flex: 1 }}
                />
              ) : (
                <span style={{ fontSize: 13.5, fontWeight: 700 }}>{sectionTitles[sec.key] ?? sec.defaultTitle}</span>
              )}
              {!editMode && (
                <span style={{ fontSize: 11.5, fontWeight: 700, color: done === items.length && items.length > 0 ? "#2E7D32" : "#9CA3AF" }}>
                  {done}/{items.length}
                </span>
              )}
            </div>
            <div ref={(el) => { listRefs.current[sec.key] = el; }}>
              {items.length === 0 && (
                <div style={{ padding: "16px", fontSize: 12.5, color: "#C2C5CB", textAlign: "center" }}>No items yet</div>
              )}
              {displayItems(sec.key, items).map((item, i) => {
                const checked = !!checklist[sec.key]?.[item.id];
                if (editMode) {
                  const isDragging = drag && drag.sectionKey === sec.key && drag.to === i;
                  return (
                    <div
                      key={item.id}
                      data-row=""
                      style={{
                        display: "flex", alignItems: "center", gap: 10, padding: "11px 16px",
                        borderBottom: i < items.length - 1 ? "1px solid #F4F5F7" : "none",
                        background: isDragging ? "#EAF2FA" : "transparent",
                        boxShadow: isDragging ? "0 2px 8px rgba(0,88,163,0.15)" : "none",
                        borderRadius: isDragging ? 8 : 0,
                        transition: "background 0.12s",
                      }}
                    >
                      <div
                        onPointerDown={(e) => startDrag(e, sec.key, items.findIndex((x) => x.id === item.id))}
                        onPointerMove={onDragMove}
                        onPointerUp={endDrag}
                        onPointerCancel={endDrag}
                        title="Drag to reorder"
                        style={{
                          flexShrink: 0, width: 28, height: 34, borderRadius: 7, cursor: "grab", touchAction: "none",
                          display: "flex", alignItems: "center", justifyContent: "center",
                          color: isDragging ? "#0058A3" : "#C2C5CB", background: isDragging ? "#DCE9F5" : "transparent",
                        }}
                      >
                        <Icon name="grip" size={16} />
                      </div>
                      <div style={{ flex: 1, minWidth: 0 }}>
                        <input
                          value={itemDraft[item.id] ?? item.text}
                          onChange={(e) => setItemDraft((d) => ({ ...d, [item.id]: e.target.value }))}
                          onBlur={() => {
                            renameItem(sec.key, item.id, itemDraft[item.id] ?? item.text);
                            setItemDraft((d) => { const n = { ...d }; delete n[item.id]; return n; });
                          }}
                          onKeyDown={(e) => { if (e.key === "Enter") e.target.blur(); }}
                          style={{ ...inputStyle, fontWeight: 400, fontSize: 13, padding: "7px 9px" }}
                        />
                        {item.remark && <div style={{ fontSize: 11, color: "#9CA3AF", marginTop: 3 }}>{item.remark}</div>}
                      </div>
                      <button
                        onClick={() => removeItem(sec.key, item.id)}
                        style={{
                          flexShrink: 0, border: "none", background: "#FDECEC", color: "#D62B2B",
                          width: 26, height: 26, borderRadius: 7, display: "flex", alignItems: "center", justifyContent: "center",
                        }}
                      >
                        <Icon name="trash" size={13} />
                      </button>
                    </div>
                  );
                }
                return (
                  <button
                    key={item.id}
                    onClick={() => toggle(sec.key, item.id)}
                    style={{
                      width: "100%", display: "flex", alignItems: "center", gap: 11, padding: "12px 16px",
                      border: "none", background: "transparent", borderBottom: i < items.length - 1 ? "1px solid #F4F5F7" : "none",
                      textAlign: "left",
                    }}
                  >
                    <span
                      style={{
                        width: 21, height: 21, borderRadius: 6, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
                        border: checked ? "none" : "1.5px solid #D1D5DB", background: checked ? sec.color : "#fff",
                      }}
                    >
                      {checked && <Icon name="check" size={13} className="" />}
                    </span>
                    <span style={{ flex: 1 }}>
                      <span style={{ display: "block", fontSize: 13, color: checked ? "#9CA3AF" : "#15181F", textDecoration: checked ? "line-through" : "none", lineHeight: 1.4 }}>
                        {item.text}
                      </span>
                      {item.remark && (
                        <span style={{ display: "block", fontSize: 11, color: "#9CA3AF", marginTop: 2, fontStyle: "italic" }}>
                          {item.remark}
                        </span>
                      )}
                    </span>
                  </button>
                );
              })}
              {editMode && (
                <div style={{ display: "flex", gap: 7, padding: "11px 14px", background: "#FAFBFC" }}>
                  <input
                    value={draftText[sec.key] || ""}
                    onChange={(e) => setDraftText({ ...draftText, [sec.key]: e.target.value })}
                    onKeyDown={(e) => { if (e.key === "Enter") addItem(sec.key); }}
                    placeholder="Add a new checklist item..."
                    style={{ ...inputStyle, fontWeight: 400, fontSize: 13, padding: "8px 11px" }}
                  />
                  <button
                    onClick={() => addItem(sec.key)}
                    style={{
                      flexShrink: 0, border: "none", background: sec.color, color: "#fff",
                      width: 36, borderRadius: 8, display: "flex", alignItems: "center", justifyContent: "center",
                    }}
                  >
                    <Icon name="plus" size={16} />
                  </button>
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

/* ===================== HISTORY VIEW ===================== */

// Compute a single day's average availability & selling rate across every round of the day
function computeDayAverages(dayChecks, timeSlots, spotsConfig) {
  // Pooled within the day: every check counts once, regardless of which round it's in. A round
  // with 2 checks no longer weighs the same as a round with 20 — the rate is simply how many
  // of the day's checks were "available" / "actively selling" out of all that qualified.
  let availNum = 0, availDen = 0; // availability: spot-level (unchanged)
  let sellYes = 0, sellTotal = 0; // selling: per individual coworker entry
  timeSlots.forEach((_, slotIdx) => {
    spotsConfig.forEach((s) => {
      const rec = dayChecks[s.id]?.[slotIdx];
      if (rec && rec.status) {
        availDen++;
        if (rec.status === "yes") availNum++;
        // collect selling entries — one per coworker if multi-format, else use rec directly
        const entries = (rec.coworkers && rec.coworkers.length)
          ? rec.coworkers.map((cw) => cw.activeSelling)
          : [rec.activeSelling];
        entries.forEach((as) => {
          if (countsTowardSelling(as)) {
            sellTotal++;
            if (getSellingVerdict(as) === "yes") sellYes++;
          }
        });
      }
    });
  });
  return {
    hasData: availDen > 0,
    availRate: availDen > 0 ? Math.round((availNum / availDen) * 100) : null,
    sellingRate: sellTotal > 0 ? Math.round((sellYes / sellTotal) * 100) : null,
    // Raw counts so a period can pool across days rather than averaging daily rates.
    availNum, availDen, sellYes, sellTotal,
  };
}

function avgOf(arr) {
  const valid = arr.filter((v) => v !== null && v !== undefined);
  if (valid.length === 0) return null;
  return Math.round(valid.reduce((a, b) => a + b, 0) / valid.length);
}

// Build a per-coworker leaderboard of Active Selling % from raw daily check records
// Counts how often each individual active-selling behaviour was ticked. The two lists are
// counted against different denominators: a "yes" behaviour is measured against the checks
// judged active-selling, a "no" reason against the checks judged not active-selling — so a
// percentage always answers "out of the times it went this way, how often was it this one".
function computeSellingItemStats(rawDayRecords, timeSlots, spotsConfig, sellingItems) {
  const counts = { yes: {}, no: {} };
  let yesChecks = 0, noChecks = 0, noCustomerChecks = 0;

  rawDayRecords.forEach(({ data }) => {
    spotsConfig.forEach((s) => {
      const slots = data[s.id];
      if (!slots) return;
      timeSlots.forEach((_, slotIdx) => {
        const rec = slots[slotIdx];
        if (!rec) return;
        // collect activeSelling entries from multi or single coworker format
        const entries = (rec.coworkers && rec.coworkers.length)
          ? rec.coworkers.map((cw) => cw.activeSelling)
          : [rec.activeSelling];
        entries.forEach((as) => {
          if (!as || typeof as === "string") return;
          const verdict = as.verdict;
          if (verdict === "nocustomer") { noCustomerChecks++; return; }
          if (verdict !== "yes" && verdict !== "no") return;
          if (verdict === "yes") yesChecks++; else noChecks++;
          const ticked = as.items || {};
          Object.keys(ticked).forEach((id) => {
            if (ticked[id]) counts[verdict][id] = (counts[verdict][id] || 0) + 1;
          });
        });
      });
    });
  });

  const build = (group, total) =>
    ((sellingItems || {})[group] || [])
      .map((it) => ({
        id: it.id,
        text: it.text,
        count: counts[group][it.id] || 0,
        pct: total > 0 ? Math.round(((counts[group][it.id] || 0) / total) * 100) : null,
      }))
      .filter((r) => r.count > 0)
      .sort((a, b) => b.count - a.count);

  return { yes: build("yes", yesChecks), no: build("no", noChecks), yesChecks, noChecks, noCustomerChecks };
}

function computeCoworkerStats(rawDayRecords, timeSlots, spotsConfig) {
  // rawDayRecords: [{ date, data: dayChecks }]
  // Supports both old format (rec.coworker + rec.activeSelling) and new multi-coworker format (rec.coworkers[])
  const byCoworker = {}; // name -> { sellYes, sellTotal, checks }
  rawDayRecords.forEach(({ data }) => {
    spotsConfig.forEach((s) => {
      const slots = data[s.id];
      if (!slots) return;
      timeSlots.forEach((_, slotIdx) => {
        const rec = slots[slotIdx];
        if (!rec) return;
        // Resolve list of { name, activeSelling } entries
        let entries = [];
        if (rec.coworkers && rec.coworkers.length) {
          entries = rec.coworkers.map((cw) => ({ name: cw.name, activeSelling: cw.activeSelling }));
        } else if (rec.coworker && rec.coworker.trim()) {
          entries = [{ name: rec.coworker.trim(), activeSelling: rec.activeSelling }];
        }
        entries.forEach(({ name, activeSelling }) => {
          if (!name || !name.trim()) return;
          const n = name.trim();
          if (!byCoworker[n]) byCoworker[n] = { sellYes: 0, sellTotal: 0, checks: 0 };
          byCoworker[n].checks++;
          if (countsTowardSelling(activeSelling)) {
            byCoworker[n].sellTotal++;
            if (getSellingVerdict(activeSelling) === "yes") byCoworker[n].sellYes++;
          }
        });
      });
    });
  });

  return Object.keys(byCoworker)
    .map((name) => {
      const c = byCoworker[name];
      return {
        name,
        checks: c.checks,
        sellingRate: c.sellTotal > 0 ? Math.round((c.sellYes / c.sellTotal) * 100) : null,
        availRate: null, // availability is now spot-level, not per individual coworker
      };
    })
    .sort((a, b) => (b.sellingRate ?? -1) - (a.sellingRate ?? -1));
}

// Build a per-spot (HFB) leaderboard of availability % and active-selling % from raw daily check records
function computeSpotStats(rawDayRecords, timeSlots, spotsConfig) {
  const bySpot = {}; // spotId -> { availYes, availTotal, sellYes, sellTotal, checks }
  rawDayRecords.forEach(({ data }) => {
    spotsConfig.forEach((s) => {
      const slots = data[s.id];
      if (!slots) return;
      timeSlots.forEach((_, slotIdx) => {
        const rec = slots[slotIdx];
        if (!rec || !rec.status) return;
        if (!bySpot[s.id]) bySpot[s.id] = { label: s.label, zone: s.zone, availYes: 0, availTotal: 0, sellYes: 0, sellTotal: 0, checks: 0 };
        bySpot[s.id].checks++;
        bySpot[s.id].availTotal++;
        if (rec.status === "yes") bySpot[s.id].availYes++;
        if (countsTowardSelling(rec.activeSelling)) {
          bySpot[s.id].sellTotal++;
          if (getSellingVerdict(rec.activeSelling) === "yes") bySpot[s.id].sellYes++;
        }
      });
    });
  });

  const rows = Object.keys(bySpot).map((id) => {
    const s = bySpot[id];
    return {
      id,
      label: s.label,
      zone: s.zone,
      checks: s.checks,
      availRate: s.availTotal > 0 ? Math.round((s.availYes / s.availTotal) * 100) : null,
      sellingRate: s.sellTotal > 0 ? Math.round((s.sellYes / s.sellTotal) * 100) : null,
    };
  });

  return {
    byAvail: [...rows].sort((a, b) => (b.availRate ?? -1) - (a.availRate ?? -1)),
    bySelling: [...rows].sort((a, b) => (b.sellingRate ?? -1) - (a.sellingRate ?? -1)),
  };
}

// Build a leaderboard of the 8 HFB groups + Self Serve — the "area" ranking used for
// Dashboard top/bottom performance, independent of whichever scope is being viewed.
function computeGroupStats(rawDayRecords, timeSlots, spotsConfig) {
  const leafScopes = HFB_GROUPS.map((g) => ({ id: g.id, label: g.label, sub: g.hfbLabel, spotIds: g.spotIds }));
  // Spots are matched to an HFB area by label, so every per-round variant of the same area
  // (e.g. "Livingroom 1" in each layout) rolls up into one group.

  const byGroup = {};
  leafScopes.forEach((g) => { byGroup[g.id] = { label: g.label, sub: g.sub, availYes: 0, availTotal: 0, sellYes: 0, sellTotal: 0, checks: 0 }; });

  rawDayRecords.forEach(({ data }) => {
    spotsConfig.forEach((s) => {
      const groupId = getHfbGroupIdForLabel(s.label);
      if (!groupId) return; // custom spot not mapped to a tracked HFB group
      const slots = data[s.id];
      if (!slots) return;
      timeSlots.forEach((_, slotIdx) => {
        const rec = slots[slotIdx];
        if (!rec || !rec.status) return;
        const g = byGroup[groupId];
        g.checks++;
        g.availTotal++;
        if (rec.status === "yes") g.availYes++;
        if (countsTowardSelling(rec.activeSelling)) {
          g.sellTotal++;
          if (getSellingVerdict(rec.activeSelling) === "yes") g.sellYes++;
        }
      });
    });
  });

  return Object.keys(byGroup).map((id) => {
    const g = byGroup[id];
    return {
      id,
      label: g.label,
      sub: g.sub,
      checks: g.checks,
      availRate: g.availTotal > 0 ? Math.round((g.availYes / g.availTotal) * 100) : null,
      sellingRate: g.sellTotal > 0 ? Math.round((g.sellYes / g.sellTotal) * 100) : null,
    };
  });
}

// Pool a period's checks (already scoped to a specific set of spots). Instead of averaging
// each day's rate — which would let a quiet day with few checks swing the number as much as a
// busy one — every check across the period is added into one pool, so the rate reflects all
// the checks equally.
function computeScopedPeriodStats(rawRecordsSubset, timeSlots, scopedSpots) {
  const dayResults = rawRecordsSubset.map(({ data }) => computeDayAverages(data, timeSlots, scopedSpots));
  const withData = dayResults.filter((d) => d.hasData);
  const availNum = withData.reduce((a, d) => a + d.availNum, 0);
  const availDen = withData.reduce((a, d) => a + d.availDen, 0);
  const sellYes = withData.reduce((a, d) => a + d.sellYes, 0);
  const sellTotal = withData.reduce((a, d) => a + d.sellTotal, 0);
  return {
    availRate: availDen > 0 ? Math.round((availNum / availDen) * 100) : null,
    sellingRate: sellTotal > 0 ? Math.round((sellYes / sellTotal) * 100) : null,
    daysLogged: withData.length,
  };
}

// Pulls EVERY logged check ever recorded (ignoring whatever filter happens to be selected on
// the Dashboard) and writes a full Excel backup — used automatically right before a reset so
// nothing is lost just because the manager left the dashboard on a narrow filter.
async function exportFullHistoryBackup(spotsConfig, timeSlots, sellingItems, checklistItems, sectionTitles) {
  const keys = await storageList("checks:");
  const dates = keys
    .map((k) => k.replace("checks:", ""))
    .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
    .sort();

  const rawRecords = await Promise.all(
    dates.map(async (date) => ({ date, data: await storageGet(`checks:${date}`, {}) }))
  );

  const maxSlots = Array.from({ length: Math.max((timeSlots.weekday || []).length, (timeSlots.weekend || []).length, 1) });

  const overallStats = computeScopedPeriodStats(rawRecords, maxSlots, spotsConfig);
  const groupStats = computeGroupStats(rawRecords, maxSlots, spotsConfig);
  const coworkerStats = computeCoworkerStats(rawRecords, maxSlots, spotsConfig);

  // Load duty assignments for all dates
  const dutyKeys = await storageList("duty:");
  const dutyDates = dutyKeys.map((k) => k.replace("duty:", "")).filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));
  const dutyEntries = await Promise.all(dutyDates.map(async (d) => [d, await storageGet(`duty:${d}`, {})]));
  const dutyByDate = Object.fromEntries(dutyEntries);

  const summaryRows = [
    { Field: "Export type", Value: "Full backup — captured automatically before reset" },
    { Field: "Date range", Value: dates.length ? `${dateLabelShort(dates[0])} to ${dateLabelShort(dates[dates.length - 1])}` : "No data" },
    { Field: "Days logged", Value: overallStats.daysLogged },
    { Field: "Coworker availability % (overall)", Value: overallStats.availRate ?? "" },
    { Field: "Active selling % (overall)", Value: overallStats.sellingRate ?? "" },
    { Field: "Exported", Value: new Date().toLocaleString("en-GB") },
  ];

  const hfbRows = [...groupStats]
    .sort((a, b) => (b.availRate ?? -1) - (a.availRate ?? -1))
    .map((g) => ({
      "HFB area": g.label,
      "HFB code": g.sub,
      "Coworker availability %": g.availRate ?? "",
      "Active selling %": g.sellingRate ?? "",
      "Checks logged": g.checks,
    }));

  const coworkerRows = [...coworkerStats]
    .sort((a, b) => (b.sellingRate ?? -1) - (a.sellingRate ?? -1))
    .map((c) => ({
      Coworker: c.name,
      "Active selling %": c.sellingRate ?? "",
      "Checks logged": c.checks,
    }));

  const rawRows = [];
  rawRecords.forEach(({ date, data }) => {
    const dt = getDayType(date);
    const dayRoundLabels = timeSlots[dt] || [];
    const dayDuty = dutyByDate[date] || {};
    const morningDuty = (dayDuty.morning || "").trim();
    const afternoonDuty = (dayDuty.afternoon || "").trim();
    spotsConfig.forEach((spot) => {
      const slots = data[spot.id];
      if (!slots) return;
      const group = findHfbGroupForSpot(spot);
      maxSlots.forEach((_, i) => {
        const rec = slots[i];
        if (!rec || !rec.status) return;
        const cwEntries = (rec.coworkers && rec.coworkers.length)
          ? rec.coworkers
          : [{ name: rec.coworker || "", activeSelling: rec.activeSelling }];
        cwEntries.forEach((cw, cwIdx) => {
          rawRows.push({
            Date: date,
            "Morning duty": morningDuty,
            "Afternoon duty": afternoonDuty,
            Round: dayRoundLabels[i] || `Round ${i + 1}`,
            "Evaluator (this round)": evaluatorForRound(dayDuty, dayRoundLabels[i]),
            "HFB area": group ? group.label : spot.zone,
            Spot: spot.label,
            Staffed: cwIdx === 0 ? (rec.status === "yes" ? "Yes" : "No") : "",
            Coworker: cw.name || "",
            "Active selling": sellingVerdictLabel(cw.activeSelling),
            "Active selling details": getSellingDetailsText(cw.activeSelling, sellingItems),
            Comment: cwIdx === 0 ? (rec.comment || "") : "",
          });
        });
      });
    });
  });
  rawRows.sort((a, b) => (a.Date < b.Date ? 1 : a.Date > b.Date ? -1 : 0));

  // Duty log
  const dutyLogRows = [...new Set([...dates, ...dutyDates])].sort().reverse().flatMap((date) => {
    const dayDuty = dutyByDate[date] || {};
    const morningName = (dayDuty.morning || "").trim();
    const afternoonName = (dayDuty.afternoon || "").trim();
    if (!morningName && !afternoonName) return [];
    const dayRec = rawRecords.find((r) => r.date === date);
    let checksLogged = 0;
    if (dayRec) {
      spotsConfig.forEach((s) => {
        const slots = dayRec.data[s.id];
        if (!slots) return;
        Object.values(slots).forEach((rec) => { if (rec && rec.status) checksLogged++; });
      });
    }
    const stats = dayRec ? computeDayAverages(dayRec.data, maxSlots, spotsConfig) : {};
    return [{
      Date: date,
      "Morning duty": morningName || "(not recorded)",
      "Afternoon duty": afternoonName || "(not recorded)",
      "Checks logged": checksLogged,
      "Coworker availability %": stats.availRate ?? "",
      "Active selling %": stats.sellingRate ?? "",
    }];
  });

  const safe = (rows, emptyNote) => (rows.length > 0 ? rows : [{ Note: emptyNote }]);

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(summaryRows), "Summary");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(hfbRows, "No HFB data")), "HFB performance");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(coworkerRows, "No coworker data")), "Coworker performance");

  const clKeys = await storageList("checklist:");
  const clDates = clKeys.map((k) => k.replace("checklist:", "")).filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d)).sort();
  const clData = await Promise.all(clDates.map(async (d) => [d, await storageGet(`checklist:${d}`, {})]));
  const clRows = [];
  clData.forEach(([d, ticks]) => {
    Object.keys(checklistItems || {}).forEach((key) => {
      const items = (checklistItems || {})[key] || [];
      if (items.length === 0) return;
      const done = items.filter((it) => ticks[key]?.[it.id]).length;
      clRows.push({
        Date: dateLabelShort(d),
        Section: (sectionTitles || {})[key] || key,
        "Items ticked": done,
        "Items expected": items.length,
        "Completion %": Math.round((done / items.length) * 100),
      });
    });
  });
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(clRows, "No checklist history")), "Checklist history");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(rawRows, "No checks logged")), "Raw log");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(dutyLogRows, "No duty history")), "Duty log");

  XLSX.writeFile(wb, `bangna-dashboard-FULL-BACKUP-before-reset-${todayKey()}.xlsx`);
}

function HistoryView({ fn, timeSlots, spotsConfig, registerExport, sellingItems, checklistItems, sectionTitles }) {
  const isSales = !fn || fn.hasMap; // Sales shows the full store dashboard (map-based KPIs)
  const hasPerPerson = !!(fn && fn.hasDuty); // Sales and CR both attribute checklist to a duty
  const perPersonLabel = fn && fn.id === "cr" ? "By CR duty" : "By shopkeeper";
  const [loading, setLoading] = useState(true);
  const [days, setDays] = useState([]); // [{date, availRate, sellingRate}] — unscoped, just to know which dates have data
  const [rawRecords, setRawRecords] = useState([]); // [{date, data}]
  const [checklistByDate, setChecklistByDate] = useState({}); // {date: {sectionKey: {itemId: true}}}
  const [dutyByDate, setDutyByDate] = useState({}); // {date: {morning, afternoon, ...}}

  const [periodType, setPeriodType] = useState("daily"); // daily | weekly | monthly | ytd
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedRound, setSelectedRound] = useState("all"); // "all" or a slot index (as string)
  const [selectedWeek, setSelectedWeek] = useState("");
  const [selectedMonth, setSelectedMonth] = useState("");
  const [scopeId, setScopeId] = useState("overall");
  const [dashTab, setDashTab] = useState("store"); // Sales dashboard sub-view: store | sk
  const [cwMetric, setCwMetric] = useState("selling"); // avail | selling — coworker panel only

  const fiscalYear = useMemo(() => getFiscalYearRange(), []);

  // Historical days may have been recorded under either weekday or weekend slot
  // counts — use the wider of the two so no recorded slot index is skipped.
  const maxSlots = useMemo(() => {
    const wd = (timeSlots && timeSlots.weekday) || [];
    const we = (timeSlots && timeSlots.weekend) || [];
    return Array.from({ length: Math.max(wd.length, we.length, 1) });
  }, [timeSlots]);

  useEffect(() => {
    (async () => {
      const keys = await storageList("checks:");
      const dates = keys
        .map((k) => k.replace("checks:", ""))
        .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
        .sort();

      const results = await Promise.all(
        dates.map(async (date) => {
          const data = await storageGet(`checks:${date}`, {});
          const avg = computeDayAverages(data, maxSlots, spotsConfig);
          return { date, data, ...avg };
        })
      );
      const withData = results.filter((d) => d.hasData);
      setRawRecords(withData.map((d) => ({ date: d.date, data: d.data })));
      setDays(withData.map(({ data, ...rest }) => rest));

      // Checklist ticks were already being written per day under checklist:<date> — this just
      // reads that history back so completion can be reported over a period.
      const clKeys = await storageList("checklist:");
      const clDates = clKeys
        .map((k) => k.replace("checklist:", ""))
        .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));
      const clEntries = await Promise.all(
        clDates.map(async (date) => [date, await storageGet(`checklist:${date}`, {})])
      );
      setChecklistByDate(Object.fromEntries(clEntries));

      // Who was on duty each day (morning/afternoon), so checklist completion can be credited
      // to the right shopkeeper. Sales duty uses the un-prefixed "duty:" keys.
      const dutyKeys = await storageList("duty:");
      const dutyDates = dutyKeys
        .map((k) => k.replace("duty:", ""))
        .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d));
      const dutyEntries = await Promise.all(
        dutyDates.map(async (date) => [date, await storageGet(`duty:${date}`, {})])
      );
      setDutyByDate(Object.fromEntries(dutyEntries));

      setLoading(false);
    })();
  }, [maxSlots, spotsConfig]);

  // Everything on this dashboard is scoped to the current IKEA physical year (1 Sep – 31 Aug)
  const fyRawRecords = useMemo(
    () => rawRecords.filter((d) => d.date >= fiscalYear.startKey && d.date <= fiscalYear.endKey),
    [rawRecords, fiscalYear]
  );

  const loggedDates = useMemo(() => [...fyRawRecords.map((d) => d.date)].sort().reverse(), [fyRawRecords]);
  const weekOptions = useMemo(() => [...new Set(loggedDates.map((d) => sundayWeekKey(d)))].sort().reverse(), [loggedDates]);
  const monthOptions = useMemo(() => [...new Set(loggedDates.map((d) => monthKey(d)))].sort().reverse(), [loggedDates]);

  // Default the pickers to the most recent available date/week/month once data loads
  useEffect(() => {
    if (!selectedDate && loggedDates.length > 0) setSelectedDate(loggedDates[0]);
    if (!selectedWeek && weekOptions.length > 0) setSelectedWeek(weekOptions[0]);
    if (!selectedMonth && monthOptions.length > 0) setSelectedMonth(monthOptions[0]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loggedDates, weekOptions, monthOptions]);

  // Rounds available for whichever date is selected (weekday vs weekend have different lists)
  const roundsForSelectedDate = useMemo(() => {
    if (!selectedDate) return [];
    const dt = getDayType(selectedDate);
    return timeSlots[dt] || [];
  }, [selectedDate, timeSlots]);

  useEffect(() => {
    setSelectedRound("all");
  }, [selectedDate]);

  // Checklist completion over the selected period. Totals are measured against today's
  // checklist config, so if a routine line was added recently, older days count as having
  // missed it — the days-logged figure alongside the % makes that easy to read.
  const checklistStats = useMemo(() => {
    const inPeriod = (date) => {
      if (date < fiscalYear.startKey || date > fiscalYear.endKey) return false;
      if (periodType === "daily") return date === selectedDate;
      if (periodType === "weekly") return sundayWeekKey(date) === selectedWeek;
      if (periodType === "monthly") return monthKey(date) === selectedMonth;
      return true;
    };

    const dates = Object.keys(checklistByDate).filter(inPeriod).sort();
    const sections = Object.keys(checklistItems || {});
    const bySection = sections.map((key) => {
      let done = 0, total = 0;
      const items = (checklistItems || {})[key] || [];
      dates.forEach((d) => {
        const ticks = checklistByDate[d]?.[key] || {};
        total += items.length;
        done += items.filter((it) => ticks[it.id]).length;
      });
      return {
        key,
        title: (sectionTitles || {})[key] || key,
        done,
        total,
        rate: total > 0 ? Math.round((done / total) * 100) : null,
      };
    }).filter((s) => s.total > 0);

    const done = bySection.reduce((a, s) => a + s.done, 0);
    const total = bySection.reduce((a, s) => a + s.total, 0);
    return {
      days: dates.length,
      done,
      total,
      rate: total > 0 ? Math.round((done / total) * 100) : null,
      bySection: [...bySection].sort((a, b) => (b.rate ?? 0) - (a.rate ?? 0)),
    };
  }, [checklistByDate, checklistItems, sectionTitles, periodType, selectedDate, selectedWeek, selectedMonth, fiscalYear]);

  // Checklist completion per shopkeeper. A day's morning sections are credited to whoever was
  // the morning duty that day, and the afternoon sections to the afternoon duty — so each SK
  // is scored only on the part of the checklist that was actually theirs. Days where no duty
  // name was recorded simply aren't credited (there's no one to attribute them to).
  const checklistByShopkeeper = useMemo(() => {
    const inPeriod = (date) => {
      if (date < fiscalYear.startKey || date > fiscalYear.endKey) return false;
      if (periodType === "daily") return date === selectedDate;
      if (periodType === "weekly") return sundayWeekKey(date) === selectedWeek;
      if (periodType === "monthly") return monthKey(date) === selectedMonth;
      return true;
    };

    const dates = Object.keys(checklistByDate).filter(inPeriod);
    const sectionKeys = Object.keys(checklistItems || {});
    const byPerson = {}; // name -> { done, total, morningDays, afternoonDays }

    const ensure = (name) => {
      if (!byPerson[name]) byPerson[name] = { name, done: 0, total: 0, morningDays: 0, afternoonDays: 0 };
      return byPerson[name];
    };

    dates.forEach((date) => {
      const duty = dutyByDate[date] || {};
      const morningName = (duty.morning || "").trim();
      const afternoonName = (duty.afternoon || "").trim();

      // Tally each section's ticks toward each shift that owns it. A section can belong to
      // both shifts (CR's report is done morning and afternoon), so morning and afternoon are
      // accumulated independently rather than as an either/or.
      let mDone = 0, mTotal = 0, aDone = 0, aTotal = 0;
      sectionKeys.forEach((key) => {
        const items = (checklistItems || {})[key] || [];
        const ticks = checklistByDate[date]?.[key] || {};
        const done = items.filter((it) => ticks[it.id]).length;
        if (sectionInShift(fn.id, key, "morning")) { mDone += done; mTotal += items.length; }
        if (sectionInShift(fn.id, key, "afternoon")) { aDone += done; aTotal += items.length; }
      });

      if (morningName && mTotal > 0) {
        const p = ensure(morningName);
        p.done += mDone; p.total += mTotal; p.morningDays += 1;
      }
      if (afternoonName && aTotal > 0) {
        const p = ensure(afternoonName);
        p.done += aDone; p.total += aTotal; p.afternoonDays += 1;
      }
    });

    return Object.values(byPerson)
      .map((p) => ({ ...p, days: p.morningDays + p.afternoonDays, rate: p.total > 0 ? Math.round((p.done / p.total) * 100) : null }))
      .sort((a, b) => (b.rate ?? -1) - (a.rate ?? -1));
  }, [checklistByDate, dutyByDate, checklistItems, periodType, selectedDate, selectedWeek, selectedMonth, fiscalYear, fn]);

  // The set of daily records that fall inside the currently selected period, with the
  // Daily + specific-round case narrowed down to just that one round.
  const periodRawRecords = useMemo(() => {
    let subset;
    if (periodType === "daily") subset = fyRawRecords.filter((r) => r.date === selectedDate);
    else if (periodType === "weekly") subset = fyRawRecords.filter((r) => sundayWeekKey(r.date) === selectedWeek);
    else if (periodType === "monthly") subset = fyRawRecords.filter((r) => monthKey(r.date) === selectedMonth);
    else subset = fyRawRecords; // ytd

    if (periodType === "daily" && selectedRound !== "all") {
      const slotIdx = Number(selectedRound);
      subset = subset.map((r) => ({ date: r.date, data: pickSlotData(r.data, slotIdx) }));
    }
    return subset;
  }, [periodType, fyRawRecords, selectedDate, selectedWeek, selectedMonth, selectedRound]);

  // A single-round day only ever has one "slot" (index 0 after pickSlotData) — use a
  // 1-length iteration array for it instead of the full maxSlots list.
  const iterSlots = periodType === "daily" && selectedRound !== "all" ? [undefined] : maxSlots;

  const scopedSpots = useMemo(() => getSpotsForScope(scopeId, spotsConfig), [scopeId, spotsConfig]);
  const scopeLabel = DASHBOARD_SCOPES.find((s) => s.id === scopeId)?.label || "Overall";

  const mainStats = useMemo(
    () => computeScopedPeriodStats(periodRawRecords, iterSlots, scopedSpots),
    [periodRawRecords, iterSlots, scopedSpots]
  );

  const groupStats = useMemo(() => computeGroupStats(periodRawRecords, iterSlots, spotsConfig), [periodRawRecords, iterSlots, spotsConfig]);
  const coworkerStats = useMemo(() => computeCoworkerStats(periodRawRecords, iterSlots, scopedSpots), [periodRawRecords, iterSlots, scopedSpots]);

  // Which specific behaviours/reasons were recorded most often across the whole period
  const sellingItemStats = useMemo(
    () => computeSellingItemStats(periodRawRecords, iterSlots, scopedSpots, sellingItems),
    [periodRawRecords, iterSlots, scopedSpots, sellingItems]
  );


  const cwRankKey = cwMetric === "avail" ? "availRate" : "sellingRate";
  const rankedCoworkers = useMemo(
    () => [...coworkerStats].filter((c) => c[cwRankKey] !== null).sort((a, b) => b[cwRankKey] - a[cwRankKey]),
    [coworkerStats, cwRankKey]
  );
  const topCoworkers = rankedCoworkers.slice(0, 3);
  const bottomCoworkers = rankedCoworkers.length > 3 ? [...rankedCoworkers].reverse().slice(0, 3) : [];

  const handleExportExcel = useCallback(() => {
    const periodTypeLabel = { daily: "Daily", weekly: "Weekly", monthly: "Monthly", ytd: "YTD" }[periodType] || periodType;
    const periodLabel =
      periodType === "daily" ? dateLabelShort(selectedDate) :
      periodType === "weekly" ? sundayWeekLabel(selectedWeek) :
      periodType === "monthly" ? monthLabel(selectedMonth) :
      `Physical year to date (${fiscalYear.label})`;
    const roundLabel = periodType === "daily"
      ? (selectedRound === "all" ? "All rounds" : `${roundsForSelectedDate[Number(selectedRound)] || ""} round`)
      : "All rounds";

    const summaryRows = [
      { Field: "Period type", Value: periodTypeLabel },
      { Field: "Period", Value: periodLabel },
      { Field: "Round", Value: roundLabel },
      { Field: "View by", Value: scopeLabel },
      { Field: "Coworker availability %", Value: mainStats.availRate ?? "" },
      { Field: "Active selling %", Value: mainStats.sellingRate ?? "" },
      { Field: "Logged days", Value: mainStats.daysLogged },
      { Field: "Checklist completion %", Value: checklistStats.rate ?? "" },
      { Field: "Checklist days logged", Value: checklistStats.days },
      { Field: "Exported", Value: new Date().toLocaleString("en-GB") },
    ];

    const hfbRows = [...groupStats]
      .sort((a, b) => (b.availRate ?? -1) - (a.availRate ?? -1))
      .map((g) => ({
        "HFB area": g.label,
        "HFB code": g.sub,
        "Coworker availability %": g.availRate ?? "",
        "Active selling %": g.sellingRate ?? "",
        "Checks logged": g.checks,
      }));

    const coworkerRows = [...coworkerStats]
      .sort((a, b) => (b.sellingRate ?? -1) - (a.sellingRate ?? -1))
      .map((c) => ({
        Coworker: c.name,
        "Coworker availability %": c.availRate ?? "",
        "Active selling %": c.sellingRate ?? "",
        "Checks logged": c.checks,
      }));

    const rawRows = [];
    periodRawRecords.forEach(({ date, data }) => {
      const dt = getDayType(date);
      const dayRoundLabels = timeSlots[dt] || [];
      const dayDuty = dutyByDate[date] || {};
      const morningDuty = (dayDuty.morning || "").trim();
      const afternoonDuty = (dayDuty.afternoon || "").trim();
      scopedSpots.forEach((spot) => {
        const slots = data[spot.id];
        if (!slots) return;
        const group = findHfbGroupForSpot(spot);
        iterSlots.forEach((_, i) => {
          const rec = slots[i];
          if (!rec || !rec.status) return;
          const label = periodType === "daily" && selectedRound !== "all"
            ? (roundsForSelectedDate[Number(selectedRound)] || `Round ${Number(selectedRound) + 1}`)
            : (dayRoundLabels[i] || `Round ${i + 1}`);
          // Resolve coworker(s) for this record
          const cwEntries = (rec.coworkers && rec.coworkers.length)
            ? rec.coworkers
            : [{ name: rec.coworker || "", activeSelling: rec.activeSelling }];
          cwEntries.forEach((cw, cwIdx) => {
            rawRows.push({
              Date: date,
              "Morning duty": morningDuty,
              "Afternoon duty": afternoonDuty,
              Round: label,
              "Evaluator (this round)": evaluatorForRound(dayDuty, dayRoundLabels[i]),
              "HFB area": group ? group.label : spot.zone,
              Spot: spot.label,
              Staffed: cwIdx === 0 ? (rec.status === "yes" ? "Yes" : "No") : "",
              Coworker: cw.name || "",
              "Active selling": sellingVerdictLabel(cw.activeSelling),
              "Active selling details": getSellingDetailsText(cw.activeSelling, sellingItems),
              Comment: cwIdx === 0 ? (rec.comment || "") : "",
            });
          });
        });
      });
    });
    rawRows.sort((a, b) => (a.Date < b.Date ? 1 : a.Date > b.Date ? -1 : 0));

    // Duty log sheet — one row per duty slot per day, with checks-logged count
    const dutyLogRows = [];
    const periodDates = periodRawRecords.map((r) => r.date);
    const allDutyDates = [...new Set([
      ...periodDates,
      ...Object.keys(dutyByDate).filter((d) => {
        if (periodType === "daily") return d === selectedDate;
        if (periodType === "weekly") return sundayWeekKey(d) === selectedWeek;
        if (periodType === "monthly") return monthKey(d) === selectedMonth;
        return d >= (fyRawRecords[fyRawRecords.length - 1]?.date || d) && d <= (fyRawRecords[0]?.date || d);
      }),
    ])].sort().reverse();

    allDutyDates.forEach((date) => {
      const dayDuty = dutyByDate[date] || {};
      const morningName = (dayDuty.morning || "").trim();
      const afternoonName = (dayDuty.afternoon || "").trim();
      // count checks logged that day (all rounds, all spots)
      const dayRec = periodRawRecords.find((r) => r.date === date);
      let checksLogged = 0;
      if (dayRec) {
        spotsConfig.forEach((s) => {
          const slots = dayRec.data[s.id];
          if (!slots) return;
          Object.values(slots).forEach((rec) => { if (rec && rec.status) checksLogged++; });
        });
      }
      if (morningName || afternoonName) {
        dutyLogRows.push({
          Date: date,
          "Morning duty": morningName || "(not recorded)",
          "Afternoon duty": afternoonName || "(not recorded)",
          "Checks logged": checksLogged,
          "Coworker availability %": dayRec ? (computeDayAverages(dayRec.data, maxSlots, spotsConfig).availRate ?? "") : "",
          "Active selling %": dayRec ? (computeDayAverages(dayRec.data, maxSlots, spotsConfig).sellingRate ?? "") : "",
        });
      }
    });

    const safe = (rows, emptyNote) => (rows.length > 0 ? rows : [{ Note: emptyNote }]);

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(summaryRows), "Summary");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(hfbRows, "No HFB data for this period")), "HFB performance");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(coworkerRows, "No coworker data for this period")), "Coworker performance");
    const checklistRows = checklistStats.bySection.map((s) => ({
      Section: s.title,
      "Items ticked": s.done,
      "Items expected": s.total,
      "Completion %": s.rate,
    }));
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(safe(checklistRows, "No checklist activity for this period")),
      "Checklist completion"
    );
    const shopkeeperRows = checklistByShopkeeper.map((p) => ({
      Shopkeeper: p.name,
      "Morning duties": p.morningDays,
      "Afternoon duties": p.afternoonDays,
      "Items ticked": p.done,
      "Items expected": p.total,
      "Completion %": p.rate,
    }));
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(safe(shopkeeperRows, "No duty assignments for this period")),
      "Checklist by shopkeeper"
    );
    const behaviourRows = [
      ...sellingItemStats.yes.map((r) => ({
        Verdict: "Active selling",
        Behaviour: r.text,
        "Times recorded": r.count,
        "% of active selling checks": r.pct,
      })),
      ...sellingItemStats.no.map((r) => ({
        Verdict: "Not active selling",
        Behaviour: r.text,
        "Times recorded": r.count,
        "% of not active selling checks": r.pct,
      })),
    ];
    XLSX.utils.book_append_sheet(
      wb,
      XLSX.utils.json_to_sheet(safe(behaviourRows, "No active selling detail for this period")),
      "Selling breakdown"
    );
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(rawRows, "No checks logged for this period")), "Raw log");
    XLSX.utils.book_append_sheet(wb, XLSX.utils.json_to_sheet(safe(dutyLogRows, "No duty assignments for this period")), "Duty log");

    const fileNamePart = selectedDate || selectedWeek || selectedMonth || "ytd";
    XLSX.writeFile(wb, `bangna-dashboard-${periodType}-${fileNamePart}.xlsx`);
  }, [
    periodType, selectedDate, selectedWeek, selectedMonth, selectedRound, roundsForSelectedDate,
    scopeLabel, mainStats, groupStats, coworkerStats, periodRawRecords, scopedSpots, timeSlots, iterSlots, fiscalYear, sellingItems, checklistStats, sellingItemStats, checklistByShopkeeper, dutyByDate, fyRawRecords, spotsConfig, maxSlots,
  ]);

  useEffect(() => {
    if (registerExport) registerExport(handleExportExcel);
  }, [registerExport, handleExportExcel]);

  if (loading) {
    return <div style={{ textAlign: "center", padding: "40px 0", color: "#9CA3AF", fontSize: 13 }}>Loading dashboard...</div>;
  }

  if (days.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "50px 20px", color: "#9CA3AF" }}>
        <Icon name="trend" size={32} className="" />
        <div style={{ fontSize: 13.5, marginTop: 12, lineHeight: 1.5 }}>
          No history yet. Once you log availability checks on the Map tab, performance will show up here.
        </div>
      </div>
    );
  }

  const periodTabs = [
    { id: "daily", label: "Daily" },
    { id: "weekly", label: "Weekly" },
    { id: "monthly", label: "Monthly" },
    { id: "ytd", label: "YTD" },
  ];

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
      {/* Period tabs */}
      <div style={{ display: "flex", gap: 6 }}>
        {periodTabs.map((pt) => (
          <button
            key={pt.id}
            onClick={() => setPeriodType(pt.id)}
            style={{
              flex: 1, padding: "8px 4px", borderRadius: 9, border: "1.5px solid",
              borderColor: periodType === pt.id ? "#0058A3" : "#E5E7EB",
              background: periodType === pt.id ? "#0058A3" : "#fff",
              color: periodType === pt.id ? "#fff" : "#374151",
              fontSize: 12, fontWeight: 700,
            }}
          >
            {pt.label}
          </button>
        ))}
      </div>

      {/* Sub-period picker */}
      {periodType === "daily" && loggedDates.length > 0 && (
        <div style={{ display: "flex", gap: 8 }}>
          <select
            value={selectedDate}
            onChange={(e) => setSelectedDate(e.target.value)}
            style={{ ...inputStyle, fontWeight: 600, fontSize: 13, padding: "9px 11px", flex: 1 }}
          >
            {loggedDates.map((d) => (
              <option key={d} value={d}>{dateLabelShort(d)}</option>
            ))}
          </select>
          <select
            value={selectedRound}
            onChange={(e) => setSelectedRound(e.target.value)}
            style={{ ...inputStyle, fontWeight: 600, fontSize: 13, padding: "9px 11px", flex: 1 }}
          >
            <option value="all">All rounds</option>
            {roundsForSelectedDate.map((t, i) => (
              <option key={i} value={i}>{t} round</option>
            ))}
          </select>
        </div>
      )}
      {periodType === "weekly" && weekOptions.length > 0 && (
        <select
          value={selectedWeek}
          onChange={(e) => setSelectedWeek(e.target.value)}
          style={{ ...inputStyle, fontWeight: 600, fontSize: 13, padding: "9px 11px" }}
        >
          {weekOptions.map((w) => (
            <option key={w} value={w}>{sundayWeekLabel(w)}</option>
          ))}
        </select>
      )}
      {periodType === "monthly" && monthOptions.length > 0 && (
        <select
          value={selectedMonth}
          onChange={(e) => setSelectedMonth(e.target.value)}
          style={{ ...inputStyle, fontWeight: 600, fontSize: 13, padding: "9px 11px" }}
        >
          {monthOptions.map((m) => (
            <option key={m} value={m}>{monthLabel(m)}</option>
          ))}
        </select>
      )}
      {periodType === "ytd" && (
        <div style={{ fontSize: 12.5, fontWeight: 600, color: "#6B7280" }}>
          Physical year to date · {fiscalYear.label}
        </div>
      )}

      {/* Functions that attribute checklist to a duty (Sales, CR) split the dashboard into a
          store/overview view and a per-person view. Kept as sub-tabs rather than a 5th
          bottom-nav tab so the bottom bar stays uncramped. */}
      {hasPerPerson && (
        <div style={{ display: "flex", gap: 6 }}>
          {[{ id: "store", label: "Store overview" }, { id: "sk", label: perPersonLabel }].map((t) => (
            <button
              key={t.id}
              onClick={() => setDashTab(t.id)}
              style={{
                flex: 1, padding: "9px 4px", borderRadius: 9, border: "1.5px solid",
                borderColor: dashTab === t.id ? "#0058A3" : "#E5E7EB",
                background: dashTab === t.id ? "#EAF2FA" : "#fff",
                color: dashTab === t.id ? "#0058A3" : "#6B7280",
                fontSize: 12.5, fontWeight: 700,
              }}
            >
              {t.label}
            </button>
          ))}
        </div>
      )}

      {/* View by (Sales store overview only) — zone row, then that zone's HFB areas. */}
      {isSales && dashTab === "store" && (
      <div>
        <div style={{ fontSize: 11.5, fontWeight: 700, color: "#6B7280", marginBottom: 6 }}>View by</div>
        <div style={{ display: "flex", gap: 6, marginBottom: 6 }}>
          {ZONE_SCOPES.map((z) => {
            const on = zoneOfScope(scopeId) === z.id;
            return (
              <button
                key={z.id}
                onClick={() => setScopeId(z.id)}
                style={{
                  flex: 1, padding: "8px 4px", borderRadius: 9, border: "1.5px solid",
                  borderColor: on ? "#0058A3" : "#E5E7EB",
                  background: on ? "#0058A3" : "#fff",
                  color: on ? "#fff" : "#374151",
                  fontSize: 11.5, fontWeight: 700, whiteSpace: "nowrap",
                }}
              >
                {z.label}
              </button>
            );
          })}
        </div>

        {(HFB_BY_ZONE[zoneOfScope(scopeId)] || []).length > 1 && (
          <div style={{ display: "flex", gap: 6, overflowX: "auto", paddingBottom: 2 }}>
            {HFB_BY_ZONE[zoneOfScope(scopeId)].map((gid) => {
              const g = HFB_GROUPS.find((x) => x.id === gid);
              if (!g) return null;
              const on = scopeId === gid;
              return (
                <button
                  key={gid}
                  onClick={() => setScopeId(on ? zoneOfScope(scopeId) : gid)}
                  style={{
                    flexShrink: 0, padding: "6px 11px", borderRadius: 8, border: "1.5px solid",
                    borderColor: on ? "#0058A3" : "#E5E7EB",
                    background: on ? "#EAF2FA" : "#fff",
                    color: on ? "#0058A3" : "#6B7280",
                    fontSize: 11.5, fontWeight: 700, whiteSpace: "nowrap",
                  }}
                >
                  {g.hfbLabel}
                </button>
              );
            })}
          </div>
        )}
      </div>
      )}

      {/* KPI row on the store overview. Sales shows all three; other functions show just the
          checklist KPI, full-width. Hidden on the per-person sub-tab. */}
      {(!hasPerPerson || dashTab === "store") && (isSales ? (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 8 }}>
          <MetricCard label="CW Availability" value={mainStats.availRate} sub={`${scopeLabel} · ${mainStats.daysLogged}d`} color="#0058A3" icon="users" />
          <MetricCard label="Active Selling" value={mainStats.sellingRate} sub={`${scopeLabel} · ${mainStats.daysLogged}d`} color="#2E7D32" icon="spark" />
          <MetricCard label="Checklist" value={checklistStats.rate} sub={`Whole store · ${checklistStats.days}d`} color="#B8590B" icon="list" />
        </div>
      ) : (
        <MetricCard label="Checklist Completion" value={checklistStats.rate} sub={`${checklistStats.days} logged day${checklistStats.days === 1 ? "" : "s"} · ${checklistStats.done}/${checklistStats.total} items`} color="#B8590B" icon="list" />
      ))}

      {/* Per-person checklist completion — its own sub-view, for functions with a duty. */}
      {hasPerPerson && dashTab === "sk" && (
        <ChecklistByShopkeeperCard people={checklistByShopkeeper} periodType={periodType} title={fn && fn.id === "cr" ? "Checklist by CR Duty" : "Checklist by Shopkeeper"} roleLabel={fn && fn.id === "cr" ? "duty" : "duty"} />
      )}

      {/* Floor-observation analysis — store overview only. */}
      {isSales && dashTab === "store" && (
      <SellingBehaviourCard stats={sellingItemStats} scopeLabel={scopeLabel} />
      )}

      {isSales && dashTab === "store" && (
      <TopBottomCard
        title={`Coworker Active Selling — ${scopeLabel}`}
        metric={cwMetric}
        setMetric={setCwMetric}
        top={topCoworkers}
        bottom={bottomCoworkers}
        nameKey="name"
        subFn={(row) => `${row.checks} check${row.checks === 1 ? "" : "s"}`}
      />
      )}

    </div>
  );
}

// Donut chart drawn with plain SVG — one arc per slice, positioned by advancing the dash
// offset around the circle. No chart library needed for something this simple.
function SellingDonut({ rows, colors }) {
  const total = rows.reduce((a, r) => a + r.count, 0);
  const cx = 70, cy = 70, r = 50, sw = 24;
  const C = 2 * Math.PI * r;
  let offset = 0;

  return (
    <svg width={140} height={140} viewBox="0 0 140 140" style={{ flexShrink: 0 }}>
      {total === 0 ? (
        <circle cx={cx} cy={cy} r={r} fill="none" stroke="#EEF0F2" strokeWidth={sw} />
      ) : (
        rows.map((row, i) => {
          const len = (row.count / total) * C;
          const el = (
            <circle
              key={row.id}
              cx={cx}
              cy={cy}
              r={r}
              fill="none"
              stroke={colors[i % colors.length]}
              strokeWidth={sw}
              strokeDasharray={`${len} ${C - len}`}
              strokeDashoffset={-offset}
              transform={`rotate(-90 ${cx} ${cy})`}
            />
          );
          offset += len;
          return el;
        })
      )}
      <text x={cx} y={cy - 2} textAnchor="middle" style={{ fontSize: 19, fontWeight: 800, fill: "#15181F" }}>
        {total}
      </text>
      <text x={cx} y={cy + 13} textAnchor="middle" style={{ fontSize: 9, fill: "#9CA3AF" }}>
        ticks
      </text>
    </svg>
  );
}

// Breakdown of the individual behaviours recorded during checks, as a donut per verdict.
// Slices are share-of-ticks within their own group (they add to 100%), while the figure in
// brackets is the share of checks — that one can exceed 100% because a single check can have
// several behaviours ticked at once.
// Per-shopkeeper checklist completion, split by the shift each person worked. Ranked
// best-first; a bar shows the rate, and the sub-line notes how many morning/afternoon duties
// fed the figure so a high or low score can be read in context.
function ChecklistByShopkeeperCard({ people, periodType, title }) {
  const label = { daily: "this day", weekly: "this week", monthly: "this month", ytd: "year to date" }[periodType] || "this period";
  const rateColor = (v) => (v === null ? "#9CA3AF" : v >= 90 ? "#2E7D32" : v >= 70 ? "#B8590B" : "#D62B2B");

  return (
    <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: "14px 16px 12px" }}>
      <div style={{ fontSize: 13.5, fontWeight: 700 }}>{title || "Checklist by Shopkeeper"}</div>
      <div style={{ fontSize: 10.5, color: "#9CA3AF", marginBottom: 12 }}>
        How completely each duty finished their shift's checklist, {label}
      </div>

      {people.length === 0 ? (
        <div style={{ textAlign: "center", padding: "16px 0", color: "#9CA3AF", fontSize: 12 }}>
          No duty assignments recorded for this period yet. Pick a name on the Duty tab so their
          checklist can be scored.
        </div>
      ) : (
        people.map((p) => {
          const parts = [];
          if (p.morningDays) parts.push(`${p.morningDays} AM`);
          if (p.afternoonDays) parts.push(`${p.afternoonDays} PM`);
          return (
            <div key={p.name} style={{ marginBottom: 11 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 9, marginBottom: 5 }}>
                <Avatar name={p.name} size={24} />
                <span style={{ fontSize: 12.5, fontWeight: 600, color: "#15181F", flex: 1, minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                  {p.name}
                  <span style={{ fontSize: 10, color: "#9CA3AF", fontWeight: 400, marginLeft: 6 }}>
                    {parts.join(" · ")} dut{p.days === 1 ? "y" : "ies"}
                  </span>
                </span>
                <span style={{ fontSize: 13.5, fontWeight: 800, color: rateColor(p.rate), flexShrink: 0 }}>
                  {p.rate === null ? "—" : `${p.rate}%`}
                </span>
              </div>
              <div style={{ height: 6, background: "#EEF0F2", borderRadius: 3, overflow: "hidden", marginLeft: 33 }}>
                <div style={{ height: "100%", width: `${p.rate ?? 0}%`, background: rateColor(p.rate), borderRadius: 3 }} />
              </div>
            </div>
          );
        })
      )}
    </div>
  );
}

function SellingBehaviourCard({ stats, scopeLabel }) {
  const YES_COLORS = ["#1D9E75", "#5DCAA5", "#0F6E56", "#9FE1CB", "#04342C"];
  const NO_COLORS = ["#E24B4A", "#F09595", "#A32D2D", "#F7C1C1", "#501313"];

  const Section = ({ title, sub, rows, colors, tone }) => {
    const total = rows.reduce((a, r) => a + r.count, 0);
    const accent = tone === "yes" ? "#2E7D32" : "#D62B2B";
    return (
      <div style={{ marginTop: tone === "yes" ? 0 : 18 }}>
        <div style={{ display: "flex", alignItems: "baseline", justifyContent: "space-between", gap: 8, marginBottom: 6 }}>
          <span style={{ fontSize: 11.5, fontWeight: 700, color: accent }}>{title}</span>
          <span style={{ fontSize: 10, color: "#9CA3AF" }}>{sub}</span>
        </div>

        {rows.length === 0 ? (
          <div style={{ padding: "12px 0", fontSize: 11.5, color: "#C2C5CB", textAlign: "center" }}>
            Nothing recorded for this period.
          </div>
        ) : (
          <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <SellingDonut rows={rows} colors={colors} />
            <div style={{ flex: 1, minWidth: 0 }}>
              {rows.map((row, i) => (
                <div key={row.id} style={{ display: "flex", alignItems: "center", gap: 7, padding: "3px 0" }}>
                  <span
                    style={{
                      width: 10, height: 10, borderRadius: 3, flexShrink: 0,
                      background: colors[i % colors.length],
                    }}
                  />
                  <span style={{ fontSize: 11.5, color: "#15181F", flex: 1, minWidth: 0, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                    {row.text}
                  </span>
                  <span style={{ fontSize: 11.5, fontWeight: 700, color: "#15181F", flexShrink: 0 }}>
                    {total > 0 ? Math.round((row.count / total) * 100) : 0}%
                  </span>
                  <span style={{ fontSize: 9.5, color: "#9CA3AF", flexShrink: 0, width: 46, textAlign: "right" }}>
                    {row.count}× ({row.pct}%)
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: "14px 16px 14px" }}>
      <div style={{ fontSize: 13.5, fontWeight: 700 }}>Active Selling Breakdown</div>
      <div style={{ fontSize: 10.5, color: "#9CA3AF", marginBottom: 12 }}>
        {scopeLabel} · share of behaviours recorded
      </div>

      <Section
        title="ACTIVE SELLING — most done"
        sub={`${stats.yesChecks} check${stats.yesChecks === 1 ? "" : "s"}`}
        rows={stats.yes}
        colors={YES_COLORS}
        tone="yes"
      />
      <Section
        title="NOT ACTIVE SELLING — most common"
        sub={`${stats.noChecks} check${stats.noChecks === 1 ? "" : "s"}`}
        rows={stats.no}
        colors={NO_COLORS}
        tone="no"
      />

      {stats.noCustomerChecks > 0 && (
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 8, marginTop: 16, padding: "9px 11px", background: "#F4F5F7", borderRadius: 9 }}>
          <span style={{ fontSize: 11.5, fontWeight: 700, color: "#6B7280" }}>No customer</span>
          <span style={{ fontSize: 11, color: "#9CA3AF" }}>
            {stats.noCustomerChecks} check{stats.noCustomerChecks === 1 ? "" : "s"} · not counted
          </span>
        </div>
      )}

      <div style={{ fontSize: 9.5, color: "#C2C5CB", marginTop: 12, lineHeight: 1.45 }}>
        Slice % is the share within its own group. The figure in brackets is how often it appeared
        across that group's checks — several behaviours can be ticked on one check, so those can total
        over 100%.
      </div>
    </div>
  );
}

function TopBottomCard({ title, metric, setMetric, top, bottom, nameKey, subKey, subFn }) {
  const valueKey = metric === "avail" ? "availRate" : "sellingRate";
  const valueColor = metric === "avail" ? "#0058A3" : "#2E7D32";

  const Row = ({ row, rank, tone }) => (
    <div style={{ display: "flex", alignItems: "center", gap: 10, padding: "9px 0" }}>
      <div
        style={{
          width: 20, height: 20, borderRadius: "50%", flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center",
          background: tone === "top" ? "#E3F3E6" : "#FDECEC",
          color: tone === "top" ? "#2E7D32" : "#D62B2B", fontSize: 10.5, fontWeight: 800,
        }}
      >
        {rank}
      </div>
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontSize: 12.5, fontWeight: 700, color: "#15181F", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          {row[nameKey]}
        </div>
        <div style={{ fontSize: 10, color: "#9CA3AF", marginTop: 1 }}>
          {subFn ? subFn(row) : (subKey && row[subKey]) || ""}
        </div>
      </div>
      <div style={{ fontSize: 14, fontWeight: 800, color: valueColor, flexShrink: 0 }}>{row[valueKey]}%</div>
    </div>
  );

  return (
    <div style={{ background: "#fff", borderRadius: 14, border: "1px solid #ECEDF0", padding: "14px 16px 12px" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: 10 }}>
        <span style={{ fontSize: 13.5, fontWeight: 700 }}>{title}</span>
        <div style={{ display: "flex", gap: 4, background: "#F4F5F7", borderRadius: 8, padding: 2 }}>
          <button
            onClick={() => setMetric("avail")}
            style={{
              padding: "4px 9px", borderRadius: 6, border: "none",
              background: metric === "avail" ? "#fff" : "transparent",
              color: metric === "avail" ? "#0058A3" : "#9CA3AF",
              fontSize: 10.5, fontWeight: 700,
              boxShadow: metric === "avail" ? "0 1px 2px rgba(0,0,0,0.08)" : "none",
            }}
          >
            Availability
          </button>
          <button
            onClick={() => setMetric("selling")}
            style={{
              padding: "4px 9px", borderRadius: 6, border: "none",
              background: metric === "selling" ? "#fff" : "transparent",
              color: metric === "selling" ? "#2E7D32" : "#9CA3AF",
              fontSize: 10.5, fontWeight: 700,
              boxShadow: metric === "selling" ? "0 1px 2px rgba(0,0,0,0.08)" : "none",
            }}
          >
            Selling
          </button>
        </div>
      </div>

      {top.length === 0 ? (
        <div style={{ textAlign: "center", padding: "16px 0", color: "#9CA3AF", fontSize: 12 }}>No data for this period yet.</div>
      ) : (
        <>
          <div style={{ fontSize: 10.5, fontWeight: 700, color: "#2E7D32", marginBottom: 2 }}>TOP 3</div>
          <div style={{ display: "flex", flexDirection: "column" }}>
            {top.map((row, i) => (
              <Row key={row.id || row.name} row={row} rank={i + 1} tone="top" />
            ))}
          </div>
          {bottom.length > 0 && (
            <>
              <div style={{ fontSize: 10.5, fontWeight: 700, color: "#D62B2B", marginTop: 8, marginBottom: 2 }}>BOTTOM 3</div>
              <div style={{ display: "flex", flexDirection: "column" }}>
                {bottom.map((row, i) => (
                  <Row key={row.id || row.name} row={row} rank={i + 1} tone="bottom" />
                ))}
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}
